/**
 * Policy Clauses — Network & System Security (p16–p22)
 * ISO 27001:2022, BSI IT-Grundschutz, NIST CSF 2.0, ISO 27001:2022, CIS Controls v8
 */
import type { PolicyClause } from "../policyClauseTemplates";

// ═══════════════════════════════════════════════════════════════
// P16 — Network Security Policy (25 clauses)
// ═══════════════════════════════════════════════════════════════
const p16: PolicyClause[] = [
  { id: "p16-c00", title: "Strategische Netzwerksicherheitsarchitektur", titleEn: "Strategic Network Security Architecture", description: "Die Organisation muss eine dokumentierte, strategische Netzwerksicherheitsarchitektur aufrechterhalten, die Sicherheitszonen, Verteidigungsschichten und Designprinzipien definiert. Die Architektur muss auf dem Defense-in-Depth-Prinzip basieren und mindestens drei Verteidigungsschichten vorsehen: Perimeter, interne Segmentierung und Host-basierte Kontrollen. Die Architektur dient als Referenzrahmen für alle Netzwerkdesign-Entscheidungen und muss mindestens jährlich und bei wesentlichen Infrastrukturänderungen überprüft werden. Operative Topologie-Details werden in p16-c14 behandelt.", descriptionEn: "The organisation must maintain a documented, strategic network security architecture defining security zones, defence layers, and design principles. The architecture must be based on the defense-in-depth principle providing at least three layers of defense: perimeter, internal segmentation, and host-based controls. The architecture serves as a reference framework for all network design decisions and must be reviewed at least annually and upon significant infrastructure changes. Operational topology details are covered in p16-c14.", reason: "Ohne strategische Architektur fehlt ein kohärenter Rahmen für Netzwerkdesign-Entscheidungen, und Sicherheitslücken können nicht systematisch identifiziert werden.", reasonEn: "Without strategic architecture, a coherent framework for network design decisions is missing, and security gaps cannot be systematically identified.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.20", "ISO 27001:2022 A.8", "BSI IT-Grundschutz NET.1.1", "CIS Controls v8 12.1"] },
  { id: "p16-c01", title: "Netzwerksegmentierung", titleEn: "Network Segmentation", description: "Netzwerke müssen nach Schutzbedarf, Funktion und Vertrauensstufe segmentiert werden. Mindestens folgende Segmente müssen getrennt werden: Produktionsumgebung, Entwicklung/Test, Management-Netzwerk, DMZ, Gäste-WLAN, OT/ICS-Netzwerke und IoT-Segmente. Zwischen den Segmenten müssen Firewalls oder vergleichbare Kontrollen den Datenverkehr filtern. Mikrosegmentierung sollte für besonders kritische Assets implementiert werden.", descriptionEn: "Networks must be segmented according to protection needs, function, and trust level. At minimum, the following segments must be separated: production environment, development/test, management network, DMZ, guest Wi-Fi, OT/ICS networks, and IoT segments. Firewalls or equivalent controls must filter traffic between segments. Micro-segmentation should be implemented for particularly critical assets.", reason: "Unzureichende Segmentierung ermöglicht laterale Bewegung von Angreifern und erhöht den Blast Radius eines Sicherheitsvorfalls erheblich.", reasonEn: "Insufficient segmentation enables lateral movement by attackers and significantly increases the blast radius of a security incident.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.22", "ISO 27001:2022 A.8", "BSI IT-Grundschutz NET.1.1", "NIST CSF 2.0 PR.IR-01", "CIS Controls v8 12.2"] },
  { id: "p16-c02", title: "Firewall-Management", titleEn: "Firewall Management", description: "Alle Firewalls müssen nach dem Prinzip der geringsten Berechtigung konfiguriert werden — standardmäßig wird der gesamte Datenverkehr blockiert, nur explizit genehmigte Verbindungen werden zugelassen (Whitelist-Ansatz). Jede Firewall-Regel muss einen dokumentierten Geschäftszweck, einen Verantwortlichen, ein Erstellungsdatum und ein Überprüfungsdatum haben. Firewall-Regelwerke müssen mindestens vierteljährlich überprüft und nicht mehr benötigte Regeln entfernt werden. Änderungen an Firewall-Regeln müssen einem Change-Management-Prozess unterliegen.", descriptionEn: "All firewalls must be configured following the principle of least privilege — all traffic is blocked by default, only explicitly approved connections are allowed (whitelist approach). Each firewall rule must have a documented business purpose, an owner, creation date, and review date. Firewall rule sets must be reviewed at least quarterly and unused rules must be removed. Changes to firewall rules must be subject to a change management process.", reason: "Veraltete, undokumentierte Firewall-Regeln sind eine der häufigsten Ursachen für Netzwerksicherheitslücken und erschweren die Incident-Response.", reasonEn: "Outdated, undocumented firewall rules are one of the most common causes of network security gaps and complicate incident response.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.20", "BSI IT-Grundschutz NET.3.2", "CIS Controls v8 4.4", "NIST CSF 2.0 PR.IR-01"] },
  { id: "p16-c03", title: "Zero Trust Network Access (ZTNA)", titleEn: "Zero Trust Network Access (ZTNA)", description: "Die Organisation muss eine Zero-Trust-Strategie für den Netzwerkzugang verfolgen. Kein Gerät oder Benutzer darf allein aufgrund seiner Netzwerkposition als vertrauenswürdig eingestuft werden. Jede Zugriffsanforderung muss authentifiziert, autorisiert und verschlüsselt werden, unabhängig davon, ob sie aus dem internen oder externen Netzwerk stammt. Kontextbasierte Zugriffsrichtlinien (Gerätegesundheit, Benutzeridentität, Standort, Uhrzeit) müssen implementiert werden.", descriptionEn: "The organisation must pursue a zero trust strategy for network access. No device or user may be classified as trustworthy based solely on network position. Every access request must be authenticated, authorised, and encrypted, regardless of whether it originates from internal or external networks. Context-based access policies (device health, user identity, location, time) must be implemented.", reason: "Das traditionelle Perimeter-Modell ist angesichts von Cloud, Remote-Arbeit und Advanced Persistent Threats unzureichend. Zero Trust reduziert die Angriffsfläche systematisch.", reasonEn: "The traditional perimeter model is insufficient given cloud, remote work, and Advanced Persistent Threats. Zero Trust systematically reduces the attack surface.", whenRequired: "Empfohlen für alle Organisationen, erforderlich bei Remote-Arbeit und Cloud-Nutzung.", whenRequiredEn: "Recommended for all organisations, required for remote work and cloud usage.", sources: ["NIST SP 800-207", "NIST CSF 2.0 PR.AA", "BSI IT-Grundschutz NET.1.1", "ISO 27001:2022 A.8"] },
  { id: "p16-c04", title: "Signaturbasierte Intrusion Detection und Prevention (IDS/IPS)", titleEn: "Signature-Based Intrusion Detection and Prevention (IDS/IPS)", description: "Die Organisation muss signaturbasierte Intrusion Detection und/oder Intrusion Prevention Systeme (IDS/IPS) an kritischen Netzwerkübergängen und innerhalb sensibler Segmente betreiben. IDS/IPS-Signaturen und Regeln müssen mindestens täglich aktualisiert werden. Alarme müssen an das Security Operations Center (SOC) oder an die verantwortliche Stelle weitergeleitet und innerhalb definierter SLAs bearbeitet werden. False-Positive-Raten müssen überwacht und optimiert werden. Für verhaltensbasierte und Anomalie-Erkennung, die über Signaturen hinausgeht, siehe p16-c10 (NDR/Anomalieerkennung).", descriptionEn: "The organisation must operate signature-based Intrusion Detection and/or Intrusion Prevention Systems (IDS/IPS) at critical network boundaries and within sensitive segments. IDS/IPS signatures and rules must be updated at least daily. Alerts must be forwarded to the Security Operations Center (SOC) or responsible function and processed within defined SLAs. False positive rates must be monitored and optimised. For behaviour-based and anomaly detection beyond signatures, see p16-c10 (NDR/Anomaly Detection).", reason: "Signaturbasierte IDS/IPS sind essentiell für die Erkennung bekannter Angriffsmuster und die Reduktion der Verweildauer (Dwell Time) von Angreifern im Netzwerk.", reasonEn: "Signature-based IDS/IPS are essential for detecting known attack patterns and reducing attacker dwell time in the network.", whenRequired: "Immer erforderlich für kritische Netzwerke.", whenRequiredEn: "Always required for critical networks.", sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz NET.3.4", "ISO 27001:2022 A.5.24-28", "NIST CSF 2.0 DE.CM-01"] },
  { id: "p16-c05", title: "VPN- und Remote-Zugangssteuerung", titleEn: "VPN and Remote Access Control", description: "Fernzugriffe auf das Organisationsnetzwerk müssen über verschlüsselte VPN-Verbindungen oder vergleichbare sichere Tunnel erfolgen. Nur genehmigte VPN-Lösungen dürfen verwendet werden. VPN-Zugänge müssen Multi-Faktor-Authentifizierung erfordern (technische MFA-Anforderungen und -Verfahren werden zentral in p11 — Authentifizierungsrichtlinie geregelt). Split-Tunneling muss standardmäßig deaktiviert sein, es sei denn, eine Risikobewertung rechtfertigt dies. VPN-Sitzungen müssen nach Inaktivität automatisch getrennt werden.", descriptionEn: "Remote access to the organisational network must be conducted via encrypted VPN connections or equivalent secure tunnels. Only approved VPN solutions may be used. VPN access must require multi-factor authentication (technical MFA requirements and procedures are centrally governed in p11 — Authentication Policy). Split tunneling must be disabled by default unless a risk assessment justifies it. VPN sessions must be automatically disconnected after inactivity.", reason: "Ungesicherte Fernzugänge sind ein primärer Angriffsvektor — kompromittierte VPN-Credentials sind für einen Großteil erfolgreicher Angriffe verantwortlich.", reasonEn: "Unsecured remote access is a primary attack vector — compromised VPN credentials account for a large portion of successful attacks.", whenRequired: "Erforderlich bei Remote-Zugang.", whenRequiredEn: "Required for remote access.", sources: ["ISO 27001:2022 A.8.20", "BSI IT-Grundschutz NET.3.3", "NIST CSF 2.0 PR.AA-05", "CIS Controls v8 12.7"] },
  { id: "p16-c06", title: "WLAN-Sicherheit", titleEn: "Wireless Network Security", description: "Drahtlose Netzwerke müssen mit WPA3-Enterprise oder gleichwertigen Standards gesichert werden. WPA2-PSK ist nur für Gästenetzwerke ohne Zugang zu internen Ressourcen zulässig. WLAN-Netzwerke müssen in einem separaten Segment betrieben werden. Rogue-Access-Point-Detection muss aktiviert sein. SSID-Broadcasting muss für interne Netzwerke evaluiert werden. Die Funkabdeckung muss auf das erforderliche Maß begrenzt werden.", descriptionEn: "Wireless networks must be secured with WPA3-Enterprise or equivalent standards. WPA2-PSK is only permissible for guest networks without access to internal resources. Wireless networks must operate in a separate segment. Rogue access point detection must be enabled. SSID broadcasting must be evaluated for internal networks. Radio coverage must be limited to the required extent.", reason: "WLAN-Netzwerke erweitern die Angriffsfläche über die physischen Grenzen der Organisation hinaus und erfordern spezifische Schutzmaßnahmen.", reasonEn: "Wireless networks extend the attack surface beyond the physical boundaries of the organisation and require specific protective measures.", whenRequired: "Erforderlich bei WLAN-Betrieb.", whenRequiredEn: "Required when operating wireless networks.", sources: ["ISO 27001:2022 A.8.20", "BSI IT-Grundschutz NET.2.1", "CIS Controls v8 12.6", "NIST CSF 2.0 PR.IR-01"] },
  { id: "p16-c07", title: "DNS-Sicherheit", titleEn: "DNS Security", description: "Die Organisation muss DNS-Sicherheitsmaßnahmen implementieren, einschließlich DNS-Filtering zur Blockierung bekannter bösartiger Domains, DNSSEC zur Validierung von DNS-Antworten und DNS-over-HTTPS/TLS für vertrauliche DNS-Anfragen. DNS-Query-Logs müssen zentral gesammelt und auf Anomalien analysiert werden. Interne DNS-Server müssen gehärtet und redundant betrieben werden.", descriptionEn: "The organisation must implement DNS security measures including DNS filtering to block known malicious domains, DNSSEC for validating DNS responses, and DNS-over-HTTPS/TLS for confidential DNS queries. DNS query logs must be centrally collected and analysed for anomalies. Internal DNS servers must be hardened and operated redundantly.", reason: "DNS ist ein bevorzugter Kanal für Datenexfiltration und Command-and-Control-Kommunikation und wird häufig von Sicherheitsmaßnahmen übersehen.", reasonEn: "DNS is a preferred channel for data exfiltration and command-and-control communication and is frequently overlooked by security measures.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["CIS Controls v8 9.2", "BSI IT-Grundschutz NET.1.1", "NIST CSF 2.0 PR.IR-01"] },
  { id: "p16-c08", title: "Netzwerkzugangskontrolle (NAC)", titleEn: "Network Access Control (NAC)", description: "Die Organisation muss Network Access Control implementieren, um sicherzustellen, dass nur autorisierte und konforme Geräte Zugang zum Netzwerk erhalten. NAC muss den Gerätegesundheitsstatus (Patch-Level, Antivirus-Status, Verschlüsselung) prüfen, bevor Zugang gewährt wird. Nicht konforme Geräte müssen in ein Quarantäne-Segment umgeleitet werden. IEEE 802.1X-Authentifizierung sollte für kabelgebundene Netzwerke implementiert werden.", descriptionEn: "The organisation must implement Network Access Control to ensure only authorised and compliant devices gain network access. NAC must verify device health status (patch level, antivirus status, encryption) before granting access. Non-compliant devices must be redirected to a quarantine segment. IEEE 802.1X authentication should be implemented for wired networks.", reason: "Ohne NAC können kompromittierte oder nicht konforme Geräte das gesamte Netzwerk gefährden.", reasonEn: "Without NAC, compromised or non-compliant devices can endanger the entire network.", whenRequired: "Empfohlen für alle Organisationen, erforderlich für kritische Infrastrukturen.", whenRequiredEn: "Recommended for all organisations, required for critical infrastructures.", sources: ["ISO 27001:2022 A.8.20", "BSI IT-Grundschutz NET.1.1", "CIS Controls v8 1.4", "NIST CSF 2.0 PR.AC"] },
  { id: "p16-c09", title: "Verschlüsselung des Netzwerkverkehrs", titleEn: "Network Traffic Encryption", description: "Datenverkehr, der Netzwerkgrenzen überschreitet oder über nicht vertrauenswürdige Netzwerke transportiert wird, muss verschlüsselt werden. TLS 1.3 ist der Mindeststandard für Anwendungsverkehr, TLS 1.2 mit sicheren Cipher-Suites ist als Fallback akzeptabel. IPsec oder WireGuard müssen für Site-to-Site-Verbindungen verwendet werden. Intern muss die Organisation eine Roadmap zur Verschlüsselung des East-West-Traffics verfolgen.", descriptionEn: "Traffic crossing network boundaries or transported over untrusted networks must be encrypted. TLS 1.3 is the minimum standard for application traffic, TLS 1.2 with secure cipher suites is acceptable as fallback. IPsec or WireGuard must be used for site-to-site connections. Internally, the organisation must pursue a roadmap for encrypting east-west traffic.", reason: "Unverschlüsselter Netzwerkverkehr kann abgefangen, manipuliert und für Man-in-the-Middle-Angriffe ausgenutzt werden.", reasonEn: "Unencrypted network traffic can be intercepted, manipulated, and exploited for man-in-the-middle attacks.", whenRequired: "Immer erforderlich für externen Verkehr, empfohlen für internen Verkehr.", whenRequiredEn: "Always required for external traffic, recommended for internal traffic.", sources: ["ISO 27001:2022 A.8.24", "ISO 27001:2022 A.8", "BSI TR-02102-2", "NIST CSF 2.0 PR.DS-02"] },
  { id: "p16-c10", title: "Verhaltensbasierte Netzwerküberwachung und NDR", titleEn: "Behaviour-Based Network Monitoring and NDR", description: "Ergänzend zu signaturbasierten IDS/IPS (p16-c04) muss der Netzwerkverkehr kontinuierlich verhaltensbasiert überwacht und auf Anomalien analysiert werden. Die Organisation muss Baseline-Profile für normalen Netzwerkverkehr erstellen und Abweichungen automatisch erkennen. Network Detection and Response (NDR) oder vergleichbare Technologien sollten implementiert werden, um fortgeschrittene Bedrohungen zu erkennen, die signaturbasierte Systeme umgehen. NetFlow/IPFIX-Daten müssen gesammelt und analysiert werden. Die Überwachung muss sowohl North-South- als auch East-West-Verkehr abdecken.", descriptionEn: "Complementing signature-based IDS/IPS (p16-c04), network traffic must be continuously monitored using behaviour-based analysis for anomalies. The organisation must create baseline profiles for normal network traffic and automatically detect deviations. Network Detection and Response (NDR) or comparable technologies should be implemented to detect advanced threats that bypass signature-based systems. NetFlow/IPFIX data must be collected and analysed. Monitoring must cover both north-south and east-west traffic.", reason: "Fortgeschrittene Angriffe (APTs, Zero-Days) umgehen signaturbasierte Erkennung. Verhaltensbasierte NDR-Technologien schließen diese Lücke.", reasonEn: "Advanced attacks (APTs, zero-days) bypass signature-based detection. Behaviour-based NDR technologies close this gap.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.16", "ISO 27001:2022 A.5.24-28", "BSI IT-Grundschutz NET.1.2", "NIST CSF 2.0 DE.AE-02"] },
  { id: "p16-c11", title: "DDoS-Schutz", titleEn: "DDoS Protection", description: "Die Organisation muss Maßnahmen zum Schutz vor Distributed-Denial-of-Service-Angriffen implementieren. Dies umfasst volumetrische Angriffe, Protokoll-Angriffe und Application-Layer-Angriffe. DDoS-Mitigation-Dienste (on-premise oder cloud-basiert) müssen für öffentlich erreichbare Dienste aktiviert sein. Eskalations- und Kommunikationspläne für DDoS-Szenarien müssen definiert sein. Regelmäßige DDoS-Simulationen müssen durchgeführt werden.", descriptionEn: "The organisation must implement measures to protect against Distributed Denial-of-Service attacks. This includes volumetric attacks, protocol attacks, and application-layer attacks. DDoS mitigation services (on-premise or cloud-based) must be activated for publicly accessible services. Escalation and communication plans for DDoS scenarios must be defined. Regular DDoS simulations must be conducted.", reason: "DDoS-Angriffe können kritische Dienste vollständig lahmlegen und sind ein häufig eingesetztes Mittel in hybriden Bedrohungsszenarien.", reasonEn: "DDoS attacks can completely disable critical services and are a frequently used tool in hybrid threat scenarios.", whenRequired: "Erforderlich für öffentlich erreichbare Dienste.", whenRequiredEn: "Required for publicly accessible services.", sources: ["ISO 27001:2022 A.8.6", "ISO 27001:2022 A.5.29-30", "BSI IT-Grundschutz NET.3.2", "NIST CSF 2.0 PR.IR-04"] },
  { id: "p16-c12", title: "E-Mail-Sicherheit", titleEn: "Email Security", description: "Die Organisation muss umfassende E-Mail-Sicherheitsmaßnahmen implementieren: SPF, DKIM und DMARC für Absendervalidierung, TLS-Verschlüsselung für den E-Mail-Transport, Anti-Spam- und Anti-Phishing-Filter mit Machine-Learning-basierter Erkennung, Sandboxing für Anhänge, URL-Rewriting und Link-Scanning. S/MIME oder PGP muss für die End-to-End-Verschlüsselung vertraulicher Kommunikation verfügbar sein.", descriptionEn: "The organisation must implement comprehensive email security measures: SPF, DKIM, and DMARC for sender validation, TLS encryption for email transport, anti-spam and anti-phishing filters with machine-learning-based detection, sandboxing for attachments, URL rewriting, and link scanning. S/MIME or PGP must be available for end-to-end encryption of confidential communications.", reason: "E-Mail ist nach wie vor der primäre Angriffsvektor für Phishing, Malware-Verbreitung und Social Engineering.", reasonEn: "Email remains the primary attack vector for phishing, malware distribution, and social engineering.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.24", "BSI IT-Grundschutz APP.5.3", "CIS Controls v8 9.5", "NIST CSF 2.0 PR.IR-01"] },
  { id: "p16-c13", title: "Web Application Firewall (WAF)", titleEn: "Web Application Firewall (WAF)", description: "Öffentlich zugängliche Webanwendungen müssen durch eine Web Application Firewall geschützt werden. Die WAF muss gegen die OWASP Top 10 Angriffe konfiguriert sein und regelmäßig auf neue Bedrohungen angepasst werden. WAF-Logs müssen in die zentrale Sicherheitsüberwachung integriert werden. Bot-Management und Rate-Limiting müssen implementiert sein.", descriptionEn: "Publicly accessible web applications must be protected by a Web Application Firewall. The WAF must be configured against the OWASP Top 10 attacks and regularly adapted to new threats. WAF logs must be integrated into central security monitoring. Bot management and rate limiting must be implemented.", reason: "Webanwendungen sind ein bevorzugtes Angriffsziel, und eine WAF bietet eine wesentliche Verteidigungsschicht zusätzlich zum sicheren Coding.", reasonEn: "Web applications are a preferred attack target, and a WAF provides an essential defence layer in addition to secure coding.", whenRequired: "Erforderlich für öffentlich zugängliche Webanwendungen.", whenRequiredEn: "Required for publicly accessible web applications.", sources: ["ISO 27001:2022 A.8.28", "BSI IT-Grundschutz APP.3.1", "OWASP", "NIST CSF 2.0 PR.IR-01"] },
  { id: "p16-c14", title: "Operative Netzwerktopologie-Dokumentation", titleEn: "Operational Network Topology Documentation", description: "Ergänzend zur strategischen Sicherheitsarchitektur (p16-c00) muss die vollständige operative Netzwerktopologie dokumentiert und aktuell gehalten werden. Dokumentation muss alle physischen und logischen Verbindungen, IP-Adressbereiche, VLAN-Zuordnungen, Routing-Tabellen, Firewall-Zonen und externe Anbindungen umfassen. Änderungen an der Netzwerkinfrastruktur müssen innerhalb von 48 Stunden in der Dokumentation nachgeführt werden. Automatisierte Netzwerk-Discovery-Tools sollten zur Validierung eingesetzt werden. Während p16-c00 die Designprinzipien und Zonenarchitektur definiert, fokussiert diese Klausel auf den aktuellen Ist-Zustand der Infrastruktur.", descriptionEn: "Complementing the strategic security architecture (p16-c00), the complete operational network topology must be documented and kept current. Documentation must include all physical and logical connections, IP address ranges, VLAN assignments, routing tables, firewall zones, and external connections. Changes to network infrastructure must be reflected in documentation within 48 hours. Automated network discovery tools should be used for validation. While p16-c00 defines design principles and zone architecture, this clause focuses on the current state of the infrastructure.", reason: "Ohne aktuelle operative Netzwerkdokumentation ist eine effektive Incident-Response, Troubleshooting und Sicherheitsanalyse unmöglich.", reasonEn: "Without current operational network documentation, effective incident response, troubleshooting, and security analysis is impossible.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.20", "BSI IT-Grundschutz NET.1.1", "CIS Controls v8 12.4"] },
  { id: "p16-c15", title: "Netzwerk-Redundanz und Hochverfügbarkeit", titleEn: "Network Redundancy and High Availability", description: "Kritische Netzwerkkomponenten (Core-Switches, Router, Firewalls, Internet-Anbindungen) müssen redundant ausgelegt sein. Automatische Failover-Mechanismen müssen implementiert und getestet werden. Single Points of Failure im Netzwerk müssen identifiziert und eliminiert werden. Die Redundanz muss die definierten RTO/RPO-Anforderungen der unterstützten Dienste erfüllen.", descriptionEn: "Critical network components (core switches, routers, firewalls, internet connections) must be designed redundantly. Automatic failover mechanisms must be implemented and tested. Single points of failure in the network must be identified and eliminated. Redundancy must meet the defined RTO/RPO requirements of supported services.", reason: "Netzwerkausfälle betreffen unmittelbar alle darauf aufbauenden Dienste und können die gesamte Organisation lahmlegen.", reasonEn: "Network outages immediately affect all dependent services and can paralyse the entire organisation.", whenRequired: "Erforderlich für kritische Netzwerkkomponenten.", whenRequiredEn: "Required for critical network components.", sources: ["ISO 27001:2022 A.8.14", "ISO 27001:2022 A.5.29-30", "BSI IT-Grundschutz NET.1.1"] },
  { id: "p16-c16", title: "Sichere Netzwerk-Administration", titleEn: "Secure Network Administration", description: "Die Administration von Netzwerkgeräten muss über ein separates Management-Netzwerk (Out-of-Band-Management) erfolgen. Unsichere Protokolle (Telnet, SNMPv1/v2, HTTP) müssen für die Administration deaktiviert werden. SSH, SNMPv3 und HTTPS sind als Mindeststandard erforderlich. Administrativer Zugang muss auf autorisierte Personen beschränkt und mit MFA gesichert sein. Alle administrativen Aktionen müssen protokolliert werden.", descriptionEn: "Administration of network devices must be conducted via a separate management network (out-of-band management). Insecure protocols (Telnet, SNMPv1/v2, HTTP) must be disabled for administration. SSH, SNMPv3, and HTTPS are required as minimum standards. Administrative access must be restricted to authorised persons and secured with MFA. All administrative actions must be logged.", reason: "Kompromittierte Netzwerkadministration ermöglicht einem Angreifer vollständige Kontrolle über das Netzwerk.", reasonEn: "Compromised network administration enables an attacker complete control over the network.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz NET.1.1", "CIS Controls v8 12.8"] },
  { id: "p16-c17", title: "Cloud-Netzwerksicherheit", titleEn: "Cloud Network Security", description: "Cloud-Netzwerke müssen die gleichen Sicherheitsstandards erfüllen wie On-Premise-Netzwerke. Virtual Private Clouds (VPCs) müssen segmentiert werden. Security Groups und Network ACLs müssen nach dem Least-Privilege-Prinzip konfiguriert werden. Cloud-Netzwerkverkehr muss überwacht werden (Flow Logs). Private Konnektivität (PrivateLink, VPN, ExpressRoute/Direct Connect) muss für sensible Workloads bevorzugt werden.", descriptionEn: "Cloud networks must meet the same security standards as on-premise networks. Virtual Private Clouds (VPCs) must be segmented. Security Groups and Network ACLs must be configured following the least privilege principle. Cloud network traffic must be monitored (Flow Logs). Private connectivity (PrivateLink, VPN, ExpressRoute/Direct Connect) must be preferred for sensitive workloads.", reason: "Cloud-Umgebungen erweitern die Netzwerkgrenzen der Organisation und erfordern angepasste Sicherheitsmaßnahmen.", reasonEn: "Cloud environments extend the network boundaries of the organisation and require adapted security measures.", whenRequired: "Erforderlich bei Cloud-Nutzung.", whenRequiredEn: "Required when using cloud services.", sources: ["ISO 27001:2022 A.8.20", "BSI C5:2020", "CIS Controls v8 12.2", "NIST CSF 2.0 PR.IR-01"] },
  { id: "p16-c18", title: "OT/ICS-Netzwerksicherheit", titleEn: "OT/ICS Network Security", description: "Operational Technology (OT) und Industrial Control Systems (ICS) müssen in strikt getrennten Netzwerksegmenten betrieben werden, die von IT-Netzwerken durch eine Demilitarized Zone (DMZ) oder Data-Dioden getrennt sind. Das Purdue-Modell oder eine vergleichbare Referenzarchitektur muss als Grundlage dienen. Direkte Verbindungen zwischen IT- und OT-Netzwerken sind verboten. OT-spezifische Protokolle müssen durch Protocol-Aware Firewalls geschützt werden.", descriptionEn: "Operational Technology (OT) and Industrial Control Systems (ICS) must be operated in strictly separated network segments, separated from IT networks by a Demilitarised Zone (DMZ) or data diodes. The Purdue Model or comparable reference architecture must serve as foundation. Direct connections between IT and OT networks are prohibited. OT-specific protocols must be protected by protocol-aware firewalls.", reason: "OT/ICS-Systeme steuern physische Prozesse. Eine Kompromittierung kann zu physischen Schäden, Produktionsausfällen und Gefährdung von Menschenleben führen.", reasonEn: "OT/ICS systems control physical processes. Compromise can lead to physical damage, production outages, and endangerment of human life.", whenRequired: "Erforderlich bei OT/ICS-Betrieb.", whenRequiredEn: "Required when operating OT/ICS.", sources: ["IEC 62443", "ISO 27001:2022 A.8", "BSI IT-Grundschutz IND.1", "NIST SP 800-82"] },
  { id: "p16-c19", title: "API-Gateway-Sicherheit", titleEn: "API Gateway Security", description: "Alle extern exponierten APIs müssen über ein zentrales API-Gateway bereitgestellt werden. Das Gateway muss Authentifizierung (OAuth 2.0/OpenID Connect), Rate-Limiting, Input-Validierung, Request-/Response-Transformation und Logging erzwingen. API-Schlüssel müssen rotiert und nicht in Client-Anwendungen hart codiert werden. API-Inventar und Dokumentation (OpenAPI/Swagger) müssen aktuell gehalten werden.", descriptionEn: "All externally exposed APIs must be provided through a central API gateway. The gateway must enforce authentication (OAuth 2.0/OpenID Connect), rate limiting, input validation, request/response transformation, and logging. API keys must be rotated and not hardcoded in client applications. API inventory and documentation (OpenAPI/Swagger) must be kept current.", reason: "APIs sind ein schnell wachsender Angriffsvektor und erfordern spezifische Sicherheitsmaßnahmen jenseits traditioneller Netzwerksicherheit.", reasonEn: "APIs are a rapidly growing attack vector requiring specific security measures beyond traditional network security.", whenRequired: "Erforderlich bei API-Exposition.", whenRequiredEn: "Required when exposing APIs.", sources: ["ISO 27001:2022 A.8.28", "OWASP API Security Top 10", "CIS Controls v8 16", "NIST CSF 2.0 PR.IR-01"] },
  { id: "p16-c20", title: "Netzwerkzugang für Dritte", titleEn: "Third-Party Network Access", description: "Netzwerkzugang für externe Dienstleister, Partner und Lieferanten muss strikt kontrolliert werden. Dritte dürfen nur auf die für ihre Aufgabe erforderlichen Netzwerkressourcen zugreifen (Jump-Server, dedizierte VLANs). Zugriffe müssen zeitlich begrenzt, protokolliert und regelmäßig überprüft werden. Permanente Fernzugänge für Dritte sind zu vermeiden. Vertragliche, Due-Diligence- und SLA-Anforderungen an Lieferanten werden zentral in p42 — Lieferantensicherheitsrichtlinie geregelt; diese Klausel fokussiert ausschließlich auf die netzwerktechnische Zugangssteuerung.", descriptionEn: "Network access for external service providers, partners, and suppliers must be strictly controlled. Third parties may only access network resources required for their task (jump servers, dedicated VLANs). Access must be time-limited, logged, and regularly reviewed. Permanent remote access for third parties should be avoided. Contractual, due diligence, and SLA requirements for suppliers are centrally governed in p42 — Supplier Security Policy; this clause focuses exclusively on network-level access controls.", reason: "Kompromittierte Drittanbieter-Zugänge sind ein häufiger Angriffsvektor (Supply-Chain-Angriffe).", reasonEn: "Compromised third-party access is a common attack vector (supply chain attacks).", whenRequired: "Erforderlich bei Netzwerkzugang für Dritte.", whenRequiredEn: "Required when granting third-party network access.", sources: ["ISO 27001:2022 A.5.20", "ISO 27001:2022 A.5.19-23", "BSI IT-Grundschutz OPS.2.4", "CIS Controls v8 12.8"] },
  { id: "p16-c21", title: "Sichere Namensauflösung und Zertifikatsmanagement", titleEn: "Secure Name Resolution and Certificate Management", description: "Die Organisation muss ein zentrales Zertifikatsmanagement implementieren. Alle TLS/SSL-Zertifikate müssen inventarisiert, mit Ablaufdaten überwacht und rechtzeitig erneuert werden. Certificate Transparency Logs müssen überwacht werden, um unautorisiert ausgestellte Zertifikate zu erkennen. Interne PKI oder ein vertrauenswürdiger externer CA-Dienst muss für die Zertifikatsausstellung verwendet werden.", descriptionEn: "The organisation must implement centralised certificate management. All TLS/SSL certificates must be inventoried, monitored for expiration dates, and renewed in time. Certificate Transparency Logs must be monitored to detect unauthorised certificate issuance. Internal PKI or a trusted external CA service must be used for certificate issuance.", reason: "Abgelaufene oder kompromittierte Zertifikate können zu Dienst­ausfällen und Man-in-the-Middle-Angriffen führen.", reasonEn: "Expired or compromised certificates can lead to service outages and man-in-the-middle attacks.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.24", "BSI TR-02102-2", "CIS Controls v8 3.10"] },
  { id: "p16-c22", title: "Netzwerk-Penetrationstests", titleEn: "Network Penetration Testing", description: "Die Organisation muss mindestens jährlich externe und interne Netzwerk-Penetrationstests durch qualifizierte, unabhängige Tester durchführen lassen. Die Tests müssen die gesamte Netzwerkinfrastruktur einschließlich Firewalls, VPN-Gateways, drahtloser Netzwerke und Cloud-Anbindungen abdecken. Identifizierte Schwachstellen müssen priorisiert, dokumentiert und innerhalb definierter Fristen behoben werden. Nachprüfungen (Re-Tests) müssen die Behebung bestätigen.", descriptionEn: "The organisation must conduct external and internal network penetration tests at least annually by qualified, independent testers. Tests must cover the entire network infrastructure including firewalls, VPN gateways, wireless networks, and cloud connections. Identified vulnerabilities must be prioritised, documented, and remediated within defined timeframes. Re-tests must confirm remediation.", reason: "Penetrationstests decken Schwachstellen auf, die automatisierten Scans entgehen, und validieren die Wirksamkeit der Netzwerksicherheitsmaßnahmen.", reasonEn: "Penetration tests uncover vulnerabilities missed by automated scans and validate the effectiveness of network security measures.", whenRequired: "Mindestens jährlich und nach wesentlichen Infrastrukturänderungen.", whenRequiredEn: "At least annually and after significant infrastructure changes.", sources: ["ISO 27001:2022 A.8.8", "ISO 27001:2022 A.8", "BSI IT-Grundschutz DER.3.3", "NIST CSF 2.0 ID.RA"] },
  { id: "p16-c23", title: "Netzwerk-Change-Management", titleEn: "Network Change Management", description: "Alle Änderungen an der Netzwerkinfrastruktur (Hardware, Konfiguration, Routing, Firewall-Regeln) müssen einem formalen Change-Management-Prozess unterliegen. Änderungen müssen beantragt, risikobewert, genehmigt, getestet und dokumentiert werden. Notfall-Änderungen (Emergency Changes) müssen einem beschleunigten Verfahren folgen, aber nachträglich dokumentiert und genehmigt werden. Rollback-Pläne müssen vor jeder Änderung definiert werden.", descriptionEn: "All changes to network infrastructure (hardware, configuration, routing, firewall rules) must be subject to a formal change management process. Changes must be requested, risk-assessed, approved, tested, and documented. Emergency changes must follow an expedited procedure but must be retrospectively documented and approved. Rollback plans must be defined before each change.", reason: "Unkontrollierte Netzwerkänderungen sind eine häufige Ursache für Ausfälle und Sicherheitslücken.", reasonEn: "Uncontrolled network changes are a common cause of outages and security gaps.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3", "ITIL Change Management"] },
  { id: "p16-c24", title: "Netzwerksicherheits-KPIs und Berichterstattung", titleEn: "Network Security KPIs and Reporting", description: "Die Organisation muss KPIs für die Netzwerksicherheit definieren und monatlich berichten. KPIs müssen mindestens umfassen: Anzahl blockierter Angriffe, IDS/IPS-Alarme und ihre Bearbeitungszeit, Firewall-Regeländerungen, Netzwerkverfügbarkeit, Patch-Status der Netzwerkgeräte, offene Schwachstellen und Mean Time to Detect/Respond für Netzwerkvorfälle.", descriptionEn: "The organisation must define network security KPIs and report monthly. KPIs must at minimum include: number of blocked attacks, IDS/IPS alerts and their processing time, firewall rule changes, network availability, patch status of network devices, open vulnerabilities, and Mean Time to Detect/Respond for network incidents.", reason: "Ohne messbare KPIs kann die Wirksamkeit der Netzwerksicherheit nicht objektiv bewertet und verbessert werden.", reasonEn: "Without measurable KPIs, the effectiveness of network security cannot be objectively assessed and improved.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §9.1", "NIST CSF 2.0 ID.IM", "BSI IT-Grundschutz OPS.1.1.1"] },
];

// ═══════════════════════════════════════════════════════════════
// P17 — Endpoint Security Policy (20 clauses)
// ═══════════════════════════════════════════════════════════════
const p17: PolicyClause[] = [
  { id: "p17-c00", title: "Endpoint-Sicherheitsstrategie", titleEn: "Endpoint Security Strategy", description: "Die Organisation muss eine umfassende Endpoint-Sicherheitsstrategie definieren, die alle Endgerätetypen abdeckt: Arbeitsplatzrechner, Laptops, Thin Clients, mobile Geräte, Server, virtuelle Desktops und IoT-Geräte. Die Strategie muss auf dem Defense-in-Depth-Prinzip basieren und präventive, detektive und reaktive Maßnahmen kombinieren.", descriptionEn: "The organisation must define a comprehensive endpoint security strategy covering all device types: workstations, laptops, thin clients, mobile devices, servers, virtual desktops, and IoT devices. The strategy must be based on defense-in-depth principle combining preventive, detective, and reactive measures.", reason: "Endpoints sind der primäre Angriffspunkt für Malware, Ransomware und andere Bedrohungen.", reasonEn: "Endpoints are the primary attack point for malware, ransomware, and other threats.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.1", "ISO 27001:2022 A.8", "BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 10"] },
  { id: "p17-c01", title: "Endpoint Detection and Response (EDR)", titleEn: "Endpoint Detection and Response (EDR)", description: "Auf allen Endpoints muss eine EDR-Lösung installiert sein, die Echtzeit-Erkennung, Verhaltensanalyse, automatische Isolation kompromittierter Geräte und forensische Datensammlung ermöglicht. EDR-Alarme müssen an das SOC oder die verantwortliche Stelle weitergeleitet werden. Die EDR-Lösung muss in die SIEM-Infrastruktur integriert sein. Anti-Tamper-Schutz muss aktiviert sein, um das Deaktivieren der Lösung zu verhindern.", descriptionEn: "An EDR solution must be installed on all endpoints providing real-time detection, behavioural analysis, automatic isolation of compromised devices, and forensic data collection. EDR alerts must be forwarded to the SOC or responsible function. The EDR solution must be integrated into the SIEM infrastructure. Anti-tamper protection must be enabled to prevent disabling the solution.", reason: "Traditionelle Antivirus-Lösungen erkennen nur bekannte Bedrohungen. EDR bietet verhaltensbasierte Erkennung und ermöglicht schnelle Eindämmung.", reasonEn: "Traditional antivirus solutions only detect known threats. EDR provides behaviour-based detection and enables rapid containment.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.7", "BSI IT-Grundschutz OPS.1.1.4", "CIS Controls v8 10.1", "NIST CSF 2.0 DE.CM-01"] },
  { id: "p17-c02", title: "Betriebssystem-Aktualisierung", titleEn: "Operating System Updates", description: "Alle Endgeräte müssen ein unterstütztes Betriebssystem verwenden, für das der Hersteller aktiv Sicherheitsupdates bereitstellt. Sicherheitsupdates müssen gemäß der Patch-Management-Richtlinie innerhalb definierter Fristen eingespielt werden. End-of-Life-Betriebssysteme müssen migriert oder durch kompensierende Kontrollen geschützt werden.", descriptionEn: "All endpoints must use a supported operating system for which the manufacturer actively provides security updates. Security updates must be applied within defined timeframes per the patch management policy. End-of-life operating systems must be migrated or protected by compensating controls.", reason: "Ungepatchte Betriebssysteme sind das häufigste Einfallstor für Angriffe.", reasonEn: "Unpatched operating systems are the most common entry point for attacks.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 7.3"] },
  { id: "p17-c03", title: "Festplattenverschlüsselung", titleEn: "Full Disk Encryption", description: "Alle mobilen Endgeräte (Laptops, Tablets) müssen eine vollständige Festplattenverschlüsselung (FDE) verwenden. BitLocker (Windows), FileVault (macOS) oder LUKS (Linux) sind als Standardlösungen definiert. Die Verschlüsselungsschlüssel müssen zentral verwaltet und in einem Escrow-System gesichert werden. Der Verschlüsselungsstatus muss zentral überwacht werden. Übergreifende Verschlüsselungsstandards (Algorithmen, Schlüssellängen, Zertifikatsmanagement) werden in p23 — Verschlüsselungsrichtlinie definiert.", descriptionEn: "All mobile endpoints (laptops, tablets) must use full disk encryption (FDE). BitLocker (Windows), FileVault (macOS), or LUKS (Linux) are defined as standard solutions. Encryption keys must be centrally managed and secured in an escrow system. Encryption status must be centrally monitored. Overarching encryption standards (algorithms, key lengths, certificate management) are defined in p23 — Encryption Policy.", reason: "Bei Verlust oder Diebstahl eines Geräts verhindert die Verschlüsselung den Zugriff auf die gespeicherten Daten.", reasonEn: "In case of device loss or theft, encryption prevents access to stored data.", whenRequired: "Immer erforderlich für mobile Geräte.", whenRequiredEn: "Always required for mobile devices.", sources: ["ISO 27001:2022 A.8.24", "BSI IT-Grundschutz SYS.2.1", "ISO 27001:2022 A.8", "CIS Controls v8 3.6"] },
  { id: "p17-c04", title: "Host-basierte Firewall", titleEn: "Host-Based Firewall", description: "Auf allen Endgeräten muss eine Host-basierte Firewall aktiviert und zentral verwaltet werden. Standardmäßig muss eingehender Verkehr blockiert werden. Ausnahmen müssen dokumentiert und genehmigt sein. Die Firewall-Konfiguration muss Manipulation durch Benutzer verhindern.", descriptionEn: "A host-based firewall must be enabled and centrally managed on all endpoints. Inbound traffic must be blocked by default. Exceptions must be documented and approved. The firewall configuration must prevent user tampering.", reason: "Host-basierte Firewalls bieten eine zusätzliche Verteidigungsschicht, insbesondere wenn Geräte außerhalb des Unternehmensnetzwerks betrieben werden.", reasonEn: "Host-based firewalls provide an additional defence layer, especially when devices operate outside the corporate network.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.20", "BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 4.5"] },
  { id: "p17-c05", title: "Application Whitelisting", titleEn: "Application Whitelisting", description: "Die Organisation sollte Application Whitelisting auf kritischen Endgeräten implementieren, um nur genehmigte Software zur Ausführung zuzulassen. Für Standardarbeitsplätze muss mindestens eine Softwarerestriktionsrichtlinie gelten, die die Ausführung von Software aus Benutzerverzeichnissen und temporären Ordnern verhindert.", descriptionEn: "The organisation should implement application whitelisting on critical endpoints to allow only approved software to execute. For standard workstations, at minimum a software restriction policy must prevent execution of software from user directories and temporary folders.", reason: "Application Whitelisting verhindert die Ausführung unbekannter Malware und reduziert die Angriffsfläche erheblich.", reasonEn: "Application whitelisting prevents execution of unknown malware and significantly reduces the attack surface.", whenRequired: "Empfohlen für alle Endgeräte, erforderlich für kritische Systeme.", whenRequiredEn: "Recommended for all endpoints, required for critical systems.", sources: ["ISO 27001:2022 A.8.19", "BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 2.5", "NIST CSF 2.0 PR.PS-01"] },
  { id: "p17-c06", title: "USB- und Peripherie-Kontrolle", titleEn: "USB and Peripheral Control", description: "Die Verwendung von USB-Geräten und anderen Peripheriegeräten muss kontrolliert werden. Standardmäßig müssen USB-Speichergeräte blockiert werden. Ausnahmen müssen genehmigt und dokumentiert werden. Autorun muss deaktiviert sein. Nur genehmigte Peripheriegeräte (Tastatur, Maus, Headset) dürfen angeschlossen werden. USB-Port-Kontrolle muss zentral verwaltet werden.", descriptionEn: "Use of USB devices and other peripherals must be controlled. USB storage devices must be blocked by default. Exceptions must be approved and documented. Autorun must be disabled. Only approved peripheral devices (keyboard, mouse, headset) may be connected. USB port control must be centrally managed.", reason: "USB-Geräte sind ein verbreiteter Angriffsvektor für Malware-Einschleusung und Datenabfluss.", reasonEn: "USB devices are a common attack vector for malware injection and data exfiltration.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.12", "BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 10.3"] },
  { id: "p17-c07", title: "Automatische Bildschirmsperre", titleEn: "Automatic Screen Lock", description: "Alle Endgeräte müssen nach maximal 10 Minuten Inaktivität automatisch gesperrt werden. Die Entsperrung muss eine erneute Authentifizierung erfordern. Für Geräte in öffentlich zugänglichen Bereichen muss eine kürzere Sperrzeit (maximal 5 Minuten) gelten. Die Einstellung darf von Benutzern nicht deaktiviert werden können.", descriptionEn: "All endpoints must automatically lock after a maximum of 10 minutes of inactivity. Unlocking must require re-authentication. For devices in publicly accessible areas, a shorter lock time (maximum 5 minutes) must apply. The setting must not be disableable by users.", reason: "Ungesperrte Geräte ermöglichen unbefugten Zugriff auf vertrauliche Informationen.", reasonEn: "Unlocked devices enable unauthorised access to confidential information.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.1", "BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 4.3"] },
  { id: "p17-c08", title: "Browser-Sicherheit", titleEn: "Browser Security", description: "Nur genehmigte und aktuelle Browser dürfen verwendet werden. Browser müssen zentral konfiguriert werden: Phishing-Schutz aktiviert, unsichere Plugins deaktiviert, Pop-up-Blocker aktiv, automatische Updates aktiviert, Zertifikatsvalidierung erzwungen. Browser-Erweiterungen müssen auf eine Whitelist beschränkt werden. Unsichere Protokolle (HTTP für sensible Inhalte) müssen blockiert werden.", descriptionEn: "Only approved and current browsers may be used. Browsers must be centrally configured: phishing protection enabled, unsafe plugins disabled, pop-up blockers active, automatic updates enabled, certificate validation enforced. Browser extensions must be limited to a whitelist. Insecure protocols (HTTP for sensitive content) must be blocked.", reason: "Browser sind das primäre Werkzeug für Webzugriff und damit ein bevorzugtes Ziel für Phishing, Drive-by-Downloads und Exploit-Kits.", reasonEn: "Browsers are the primary tool for web access and thus a preferred target for phishing, drive-by downloads, and exploit kits.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.19", "BSI IT-Grundschutz APP.1.2", "CIS Controls v8 9.1"] },
  { id: "p17-c09", title: "Endgeräte-Inventar und Lifecycle-Management", titleEn: "Endpoint Inventory and Lifecycle Management", description: "Alle Endgeräte müssen in einem zentralen Inventar erfasst sein — Gerätename, Typ, Betriebssystem, Seriennummer, Benutzer, Standort, Sicherheitsstatus. Der gesamte Geräte-Lifecycle muss verwaltet werden: Beschaffung, Konfiguration, Bereitstellung, Nutzung, Wartung, Außerbetriebnahme und sichere Entsorgung. Das Endpoint-Inventar muss mit dem zentralen CMDB/Asset-Inventar (p08 — Technical Inventory Policy) synchronisiert werden, um Konsistenz und Vollständigkeit sicherzustellen.", descriptionEn: "All endpoints must be recorded in a central inventory — device name, type, operating system, serial number, user, location, security status. The entire device lifecycle must be managed: procurement, configuration, provisioning, usage, maintenance, decommissioning, and secure disposal. The endpoint inventory must be synchronised with the central CMDB/asset inventory (p08 — Technical Inventory Policy) to ensure consistency and completeness.", reason: "Ohne vollständiges Inventar ist die Sicherheitslage der Endgeräte nicht bewertbar.", reasonEn: "Without complete inventory, the security posture of endpoints cannot be assessed.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.9", "BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 1.1"] },
  { id: "p17-c10", title: "Ransomware-Schutz", titleEn: "Ransomware Protection", description: "Die Organisation muss spezifische Maßnahmen zum Schutz vor Ransomware implementieren: kontrollierte Ordnerzugriffe (Controlled Folder Access), regelmäßige Offline-Backups, Einschränkung von Makros und Skripten, Netzwerksegmentierung zur Begrenzung der Ausbreitung, Schulung der Mitarbeiter zur Erkennung von Phishing, und Incident-Response-Pläne speziell für Ransomware-Szenarien.", descriptionEn: "The organisation must implement specific ransomware protection measures: controlled folder access, regular offline backups, restriction of macros and scripts, network segmentation to limit spread, employee training for phishing recognition, and incident response plans specifically for ransomware scenarios.", reason: "Ransomware ist die derzeit größte Bedrohung für Organisationen aller Größen und Branchen.", reasonEn: "Ransomware is currently the greatest threat to organisations of all sizes and sectors.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.7", "BSI IT-Grundschutz OPS.1.1.4", "ISO 27001:2022 A.5.24-28", "NIST CSF 2.0 PR.PS"] },
  { id: "p17-c11", title: "Lokale Administratorrechte", titleEn: "Local Administrator Rights", description: "Standardbenutzer dürfen keine lokalen Administratorrechte auf ihren Endgeräten besitzen. Für administrative Aufgaben muss ein separates privilegiertes Konto verwendet werden (Privilege Elevation). Ausnahmen müssen dokumentiert, zeitlich begrenzt und genehmigt werden. Local Administrator Password Solution (LAPS) oder vergleichbare Lösungen müssen implementiert werden. Die zentrale PAM-Strategie (Just-in-Time-Zugang, Sitzungsaufzeichnung, Tresor-Management) wird in p12 — Privileged Access Management Policy definiert; diese Klausel regelt die lokale Umsetzung auf Endgeräteebene.", descriptionEn: "Standard users must not have local administrator rights on their endpoints. A separate privileged account must be used for administrative tasks (privilege elevation). Exceptions must be documented, time-limited, and approved. Local Administrator Password Solution (LAPS) or comparable solutions must be implemented. The central PAM strategy (just-in-time access, session recording, vault management) is defined in p12 — Privileged Access Management Policy; this clause governs local implementation at the endpoint level.", reason: "Lokale Administratorrechte sind der wichtigste Enabler für Malware-Installation und Privilege Escalation.", reasonEn: "Local administrator rights are the most important enabler for malware installation and privilege escalation.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.2", "BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 5.4"] },
  { id: "p17-c12", title: "Sichere Konfiguration neuer Endgeräte", titleEn: "Secure Configuration of New Endpoints", description: "Neue Endgeräte müssen vor der Bereitstellung an Benutzer nach einer dokumentierten Sicherheitsbaseline konfiguriert werden. Die Baseline muss umfassen: Festplattenverschlüsselung, EDR-Installation, Firewall-Aktivierung, aktuelle Patches, sichere Browser-Konfiguration, Deaktivierung unnötiger Dienste und Ports. Golden Images oder automatisierte Deployment-Pipelines müssen verwendet werden.", descriptionEn: "New endpoints must be configured according to a documented security baseline before deployment to users. The baseline must include: disk encryption, EDR installation, firewall activation, current patches, secure browser configuration, disabling unnecessary services and ports. Golden images or automated deployment pipelines must be used.", reason: "Ein unsicher konfiguriertes Gerät ist vom ersten Moment an verwundbar.", reasonEn: "An insecurely configured device is vulnerable from the first moment.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 4.1"] },
  { id: "p17-c13", title: "Sichere Außerbetriebnahme von Endgeräten", titleEn: "Secure Endpoint Decommissioning", description: "Bei der Außerbetriebnahme von Endgeräten müssen alle Daten sicher gelöscht werden (NIST SP 800-88 Guidelines). Für SSDs muss Secure Erase oder physische Vernichtung verwendet werden. Der Löschvorgang muss dokumentiert und bestätigt werden. Leasing-Geräte müssen vor der Rückgabe vollständig gelöscht werden.", descriptionEn: "During endpoint decommissioning, all data must be securely erased (NIST SP 800-88 Guidelines). For SSDs, Secure Erase or physical destruction must be used. The erasure process must be documented and confirmed. Leased devices must be completely wiped before return.", reason: "Unzureichend gelöschte Datenträger führen regelmäßig zu Datenlecks.", reasonEn: "Insufficiently erased storage media regularly lead to data leaks.", whenRequired: "Immer bei Geräte-Außerbetriebnahme.", whenRequiredEn: "Always during device decommissioning.", sources: ["ISO 27001:2022 A.7.14", "BSI IT-Grundschutz SYS.2.1", "NIST SP 800-88"] },
  { id: "p17-c14", title: "Remote-Arbeit Endgerätesicherheit", titleEn: "Remote Work Endpoint Security", description: "Endgeräte, die für Remote-Arbeit verwendet werden, müssen dieselben Sicherheitsstandards erfüllen wie Geräte im Büro. Zusätzlich müssen VPN-Nutzung, getrennte Arbeits-/Privatnutzung, physische Sicherheit am Heimarbeitsplatz und sichere WLAN-Nutzung geregelt werden. Always-On-VPN oder ZTNA-Lösungen müssen für Remote-Geräte aktiviert werden.", descriptionEn: "Endpoints used for remote work must meet the same security standards as office devices. Additionally, VPN usage, separation of work/personal use, physical security at home workplaces, and secure Wi-Fi usage must be regulated. Always-on VPN or ZTNA solutions must be activated for remote devices.", reason: "Remote-Arbeitsplätze befinden sich außerhalb der physischen und netzwerkseitigen Kontrolle der Organisation.", reasonEn: "Remote workplaces are outside the physical and network-side control of the organisation.", whenRequired: "Erforderlich bei Remote-Arbeit.", whenRequiredEn: "Required for remote work.", sources: ["ISO 27001:2022 A.6.7", "BSI IT-Grundschutz INF.9", "ISO 27001:2022 A.8"] },
  { id: "p17-c15", title: "Endgeräte-Compliance-Überwachung", titleEn: "Endpoint Compliance Monitoring", description: "Der Compliance-Status aller Endgeräte muss kontinuierlich überwacht werden. Nicht konforme Geräte (fehlende Patches, deaktivierter Virenschutz, abgelaufene Zertifikate) müssen automatisch erkannt und in den Netzwerkzugang eingeschränkt werden. Compliance-Dashboards müssen der IT-Sicherheitsleitung zur Verfügung stehen.", descriptionEn: "The compliance status of all endpoints must be continuously monitored. Non-compliant devices (missing patches, disabled antivirus, expired certificates) must be automatically detected and restricted in network access. Compliance dashboards must be available to IT security management.", reason: "Ohne kontinuierliche Überwachung verschlechtert sich der Sicherheitszustand der Endgeräteflotte schnell.", reasonEn: "Without continuous monitoring, the security posture of the endpoint fleet deteriorates quickly.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.1", "CIS Controls v8 1.3", "NIST CSF 2.0 DE.CM-01"] },
  { id: "p17-c16", title: "Makro- und Skript-Kontrolle", titleEn: "Macro and Script Control", description: "Die Ausführung von Makros in Office-Dokumenten muss standardmäßig blockiert werden, mit Ausnahme signierter und genehmigter Makros. PowerShell muss im Constrained Language Mode betrieben und Script-Block-Logging aktiviert werden. Windows Script Host (WSH) muss auf Standardarbeitsplätzen deaktiviert werden. AMSI (Antimalware Scan Interface) muss aktiviert sein.", descriptionEn: "Execution of macros in Office documents must be blocked by default, except for signed and approved macros. PowerShell must operate in Constrained Language Mode with script block logging enabled. Windows Script Host (WSH) must be disabled on standard workstations. AMSI (Antimalware Scan Interface) must be enabled.", reason: "Makros und Skripte sind die häufigsten Vektoren für initiale Kompromittierung in gezielten Angriffen.", reasonEn: "Macros and scripts are the most common vectors for initial compromise in targeted attacks.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.19", "BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 2.7"] },
  { id: "p17-c17", title: "Endgeräte-Forensik-Bereitschaft", titleEn: "Endpoint Forensic Readiness", description: "Endgeräte müssen so konfiguriert sein, dass bei einem Sicherheitsvorfall ausreichende forensische Daten verfügbar sind. Dies umfasst: erweiterte Audit-Protokollierung, Sysmon oder vergleichbare Telemetrie, EDR-Datenretention und Möglichkeit zur forensischen Sicherung (Imaging) ohne Datenverlust. Die Eskalations- und Meldeprozesse bei erkannten Endpunkt-Vorfällen richten sich nach p31 — Incident Reporting Policy.", descriptionEn: "Endpoints must be configured so that sufficient forensic data is available during a security incident. This includes: extended audit logging, Sysmon or comparable telemetry, EDR data retention, and capability for forensic preservation (imaging) without data loss. Escalation and reporting processes for detected endpoint incidents follow p31 — Incident Reporting Policy.", reason: "Ohne vorbereitete Forensik-Fähigkeiten ist die Aufklärung und Eindämmung von Sicherheitsvorfällen erheblich erschwert.", reasonEn: "Without prepared forensic capabilities, investigation and containment of security incidents is significantly impaired.", whenRequired: "Empfohlen für alle Endgeräte, erforderlich für kritische Systeme.", whenRequiredEn: "Recommended for all endpoints, required for critical systems.", sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz DER.2.2", "NIST CSF 2.0 RS.AN"] },
  { id: "p17-c18", title: "BYOD-Sicherheit", titleEn: "BYOD Security", description: "Wenn die Organisation Bring-Your-Own-Device (BYOD) erlaubt, müssen spezifische Sicherheitsanforderungen gelten: Container-Lösung für Unternehmensdaten, MDM-Enrollment, Mindestsicherheitsstandards (Betriebssystemversion, Verschlüsselung, PIN), Remote-Wipe-Fähigkeit für Unternehmensdaten und Netzwerksegmentierung. BYOD-Geräte dürfen keinen direkten Zugang zu kritischen Netzwerksegmenten erhalten.", descriptionEn: "If the organisation permits Bring-Your-Own-Device (BYOD), specific security requirements must apply: containerisation for corporate data, MDM enrolment, minimum security standards (OS version, encryption, PIN), remote wipe capability for corporate data, and network segmentation. BYOD devices must not receive direct access to critical network segments.", reason: "BYOD-Geräte unterliegen nicht der vollständigen Kontrolle der Organisation und stellen ein erhöhtes Sicherheitsrisiko dar.", reasonEn: "BYOD devices are not under the organisation's full control and represent an elevated security risk.", whenRequired: "Erforderlich bei BYOD-Erlaubnis.", whenRequiredEn: "Required when BYOD is permitted.", sources: ["ISO 27001:2022 A.8.1", "BSI IT-Grundschutz SYS.3.2.1", "CIS Controls v8 1.2"] },
  { id: "p17-c19", title: "Endgeräte-Backup", titleEn: "Endpoint Backup", description: "Kritische Daten auf Endgeräten müssen regelmäßig gesichert werden — vorzugsweise automatisiert über Cloud-Synchronisation oder zentrales Backup. Lokale Datenspeicherung auf Endgeräten muss minimiert werden zugunsten zentraler Speicherlösungen. Backup-Integrität muss regelmäßig überprüft werden.", descriptionEn: "Critical data on endpoints must be regularly backed up — preferably automated via cloud synchronisation or central backup. Local data storage on endpoints must be minimised in favour of central storage solutions. Backup integrity must be regularly verified.", reason: "Datenverlust durch Geräteschäden, Diebstahl oder Ransomware kann ohne Backup irreversibel sein.", reasonEn: "Data loss due to device damage, theft, or ransomware can be irreversible without backup.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.13", "BSI IT-Grundschutz CON.3", "CIS Controls v8 11.1"] },
];

// ═══════════════════════════════════════════════════════════════
// P18 — System Hardening Policy (22 clauses)
// ═══════════════════════════════════════════════════════════════
const p18: PolicyClause[] = [
  { id: "p18-c00", title: "Härtungsstandards und Baselines", titleEn: "Hardening Standards and Baselines", description: "Die Organisation muss dokumentierte Härtungsstandards für alle Systemklassen definieren — Server (Windows, Linux), Netzwerkgeräte, Datenbanken, Container, Cloud-Instanzen. Die Standards müssen auf anerkannten Benchmarks basieren (CIS Benchmarks, DISA STIGs, BSI-Grundschutz-Bausteine). Für jede Systemklasse muss eine Sicherheitsbaseline definiert und versioniert werden.", descriptionEn: "The organisation must define documented hardening standards for all system classes — servers (Windows, Linux), network devices, databases, containers, cloud instances. Standards must be based on recognised benchmarks (CIS Benchmarks, DISA STIGs, BSI Grundschutz modules). A security baseline must be defined and versioned for each system class.", reason: "Ohne einheitliche Härtungsstandards variiert das Sicherheitsniveau zwischen Systemen erheblich.", reasonEn: "Without uniform hardening standards, security levels vary significantly between systems.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz SYS.1.1", "CIS Controls v8 4.1", "NIST CSF 2.0 PR.PS-01"] },
  { id: "p18-c01", title: "Minimale Dienste und Funktionen", titleEn: "Minimal Services and Functions", description: "Systeme dürfen nur die für ihren Zweck erforderlichen Dienste, Ports, Protokolle und Funktionen aktiviert haben. Alle nicht benötigten Dienste müssen deaktiviert oder deinstalliert werden. Nicht benötigte Benutzerkonten (insbesondere Standardkonten) müssen deaktiviert oder entfernt werden. Der Zweck jedes aktiven Dienstes muss dokumentiert sein.", descriptionEn: "Systems must only have services, ports, protocols, and functions activated that are required for their purpose. All unnecessary services must be disabled or uninstalled. Unnecessary user accounts (especially default accounts) must be disabled or removed. The purpose of each active service must be documented.", reason: "Jeder aktive Dienst vergrößert die Angriffsfläche und bietet potenzielle Einstiegspunkte für Angreifer.", reasonEn: "Every active service increases the attack surface and provides potential entry points for attackers.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz SYS.1.1", "CIS Controls v8 4.8"] },
  { id: "p18-c02", title: "Sichere Boot-Konfiguration", titleEn: "Secure Boot Configuration", description: "Secure Boot und UEFI müssen auf allen unterstützten Systemen aktiviert sein, um die Integrität des Boot-Prozesses sicherzustellen. Trusted Platform Module (TPM) 2.0 muss für Schlüsselspeicherung und Measured Boot verwendet werden. Legacy-BIOS-Boot muss deaktiviert werden. Boot-Reihenfolge muss auf die interne Festplatte beschränkt sein.", descriptionEn: "Secure Boot and UEFI must be enabled on all supported systems to ensure boot process integrity. Trusted Platform Module (TPM) 2.0 must be used for key storage and measured boot. Legacy BIOS boot must be disabled. Boot order must be restricted to the internal hard drive.", reason: "Ohne Secure Boot können Rootkits und Bootkits die Systemintegrität vor dem Laden des Betriebssystems kompromittieren.", reasonEn: "Without Secure Boot, rootkits and bootkits can compromise system integrity before the operating system loads.", whenRequired: "Immer erforderlich für neue Systeme.", whenRequiredEn: "Always required for new systems.", sources: ["BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 4.1", "NIST CSF 2.0 PR.PS-01"] },
  { id: "p18-c03", title: "Dateisystem-Sicherheit", titleEn: "File System Security", description: "Dateisystem-Berechtigungen müssen nach dem Least-Privilege-Prinzip konfiguriert werden. Systemverzeichnisse dürfen nur von administrativen Konten beschreibbar sein. Temporäre Verzeichnisse müssen mit noexec-Flag gemountet werden (Linux). NTFS-Berechtigungen müssen regelmäßig überprüft werden. Dateisystem-Auditing muss für sicherheitsrelevante Verzeichnisse aktiviert sein.", descriptionEn: "File system permissions must be configured following the least privilege principle. System directories must only be writable by administrative accounts. Temporary directories must be mounted with noexec flag (Linux). NTFS permissions must be regularly reviewed. File system auditing must be enabled for security-relevant directories.", reason: "Fehlerhafte Dateisystem-Berechtigungen ermöglichen Privilege Escalation und unbefugten Datenzugriff.", reasonEn: "Incorrect file system permissions enable privilege escalation and unauthorised data access.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.3", "BSI IT-Grundschutz SYS.1.1", "CIS Controls v8 3.3"] },
  { id: "p18-c04", title: "Registrierungs- und Kernel-Härtung", titleEn: "Registry and Kernel Hardening", description: "Windows-Registrierung muss gehärtet werden: SMBv1 deaktiviert, LLMNR/NetBIOS deaktiviert, Credential Caching minimiert, Remote-Registry deaktiviert. Linux-Kernel-Parameter müssen gehärtet werden: ASLR aktiviert, Kernel-Pointer-Leaks verhindert, unprivilegiertes BPF deaktiviert, sysctl-Härtung gemäß CIS Benchmarks.", descriptionEn: "Windows registry must be hardened: SMBv1 disabled, LLMNR/NetBIOS disabled, credential caching minimised, remote registry disabled. Linux kernel parameters must be hardened: ASLR enabled, kernel pointer leaks prevented, unprivileged BPF disabled, sysctl hardening per CIS Benchmarks.", reason: "Kernel und Registry-Einstellungen sind die tiefste Verteidigungsschicht und haben erheblichen Einfluss auf die Angriffsfläche.", reasonEn: "Kernel and registry settings are the deepest defence layer and have significant impact on the attack surface.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["CIS Benchmarks", "BSI IT-Grundschutz SYS.1.1", "NIST SP 800-123"] },
  { id: "p18-c05", title: "Datenbank-Härtung", titleEn: "Database Hardening", description: "Datenbanksysteme müssen gehärtet werden: Standardports ändern, unnötige Features deaktivieren, Netzwerkzugriff auf autorisierte Quellen beschränken, Datenbank-Auditing aktivieren, Verschlüsselung für Daten in Ruhe (TDE) und in Transit (TLS) konfigurieren, regelmäßige Sicherheitspatches einspielen, Standardbenutzer deaktivieren oder Passwörter ändern. Übergreifende Verschlüsselungsstandards (Algorithmen, Schlüssellängen, Zertifikatsmanagement) werden zentral in p23 — Verschlüsselungsrichtlinie definiert.", descriptionEn: "Database systems must be hardened: change default ports, disable unnecessary features, restrict network access to authorised sources, enable database auditing, configure encryption for data at rest (TDE) and in transit (TLS), apply regular security patches, disable default users or change passwords. Overarching encryption standards (algorithms, key lengths, certificate management) are centrally defined in p23 — Encryption Policy.", reason: "Datenbanken enthalten die wertvollsten Informationen der Organisation und sind ein primäres Ziel für Angreifer.", reasonEn: "Databases contain the organisation's most valuable information and are a primary target for attackers.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz APP.4.3", "CIS Benchmarks"] },
  { id: "p18-c06", title: "Container- und Kubernetes-Härtung", titleEn: "Container and Kubernetes Hardening", description: "Container müssen mit minimalen Base-Images erstellt, als Non-Root-Benutzer ausgeführt und mit Read-Only-Dateisystemen konfiguriert werden. Kubernetes-Cluster müssen gehärtet werden: RBAC erzwungen, Pod Security Standards implementiert, Network Policies aktiv, etcd verschlüsselt, API-Server-Zugriff eingeschränkt. Container-Images müssen vor dem Deployment auf Schwachstellen gescannt werden.", descriptionEn: "Containers must be built with minimal base images, run as non-root users, and configured with read-only file systems. Kubernetes clusters must be hardened: RBAC enforced, Pod Security Standards implemented, Network Policies active, etcd encrypted, API server access restricted. Container images must be scanned for vulnerabilities before deployment.", reason: "Container-Umgebungen bieten eine große Angriffsfläche, wenn sie nicht korrekt gehärtet werden.", reasonEn: "Container environments provide a large attack surface when not correctly hardened.", whenRequired: "Erforderlich bei Container-/Kubernetes-Nutzung.", whenRequiredEn: "Required when using containers/Kubernetes.", sources: ["CIS Kubernetes Benchmark", "BSI IT-Grundschutz SYS.1.6", "NIST SP 800-190"] },
  { id: "p18-c07", title: "Cloud-Instanzen-Härtung", titleEn: "Cloud Instance Hardening", description: "Cloud-Instanzen müssen nach denselben Härtungsstandards wie On-Premise-Systeme konfiguriert werden. Zusätzlich müssen cloud-spezifische Härtungsmaßnahmen umgesetzt werden: Instance Metadata Service (IMDS) v2 erzwungen, öffentliche IP-Adressen vermieden, Security Groups nach Least-Privilege konfiguriert, Cloud-native Verschlüsselung aktiviert.", descriptionEn: "Cloud instances must be configured according to the same hardening standards as on-premise systems. Additionally, cloud-specific hardening measures must be implemented: Instance Metadata Service (IMDS) v2 enforced, public IP addresses avoided, Security Groups configured per least privilege, cloud-native encryption enabled.", reason: "Fehlkonfigurierte Cloud-Instanzen sind eine der häufigsten Ursachen für Datenlecks.", reasonEn: "Misconfigured cloud instances are one of the most common causes of data breaches.", whenRequired: "Erforderlich bei Cloud-Nutzung.", whenRequiredEn: "Required when using cloud services.", sources: ["ISO 27001:2022 A.8.9", "BSI C5:2020", "CIS Cloud Benchmarks", "NIST CSF 2.0 PR.PS-01"] },
  { id: "p18-c08", title: "Automatisierte Härtungsprüfung", titleEn: "Automated Hardening Verification", description: "Der Härtungsstatus aller Systeme muss regelmäßig automatisiert überprüft und bewertet werden. Tools wie CIS-CAT, OpenSCAP, Qualys oder vergleichbare Lösungen müssen für Scanning und Reporting eingesetzt werden. Abweichungen von der definierten Baseline müssen automatisch gemeldet und innerhalb definierter Fristen zur Behebung eskaliert werden. Der Compliance-Grad muss als KPI überwacht werden. Diese Klausel fokussiert auf die Prüfung und Bewertung; die automatische Korrektur und Durchsetzung von Härtungseinstellungen wird in p18-c21 geregelt. Für baseline-spezifische Drift-Erkennung im Konfigurationsmanagement-Kontext siehe zusätzlich p19-c04.", descriptionEn: "The hardening status of all systems must be regularly verified and assessed automatically. Tools such as CIS-CAT, OpenSCAP, Qualys, or comparable solutions must be used for scanning and reporting. Deviations from the defined baseline must be automatically reported and escalated for remediation within defined timeframes. The compliance degree must be monitored as a KPI. This clause focuses on verification and assessment; automatic correction and enforcement of hardening settings is governed in p18-c21. For baseline-specific drift detection in the configuration management context, see additionally p19-c04.", reason: "Manuelle Härtungsprüfungen sind bei größeren Umgebungen nicht skalierbar und fehleranfällig.", reasonEn: "Manual hardening checks are not scalable for larger environments and error-prone.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "CIS Controls v8 4.1", "NIST CSF 2.0 DE.CM-09"] },
  { id: "p18-c09", title: "Härtung bei Systemänderungen", titleEn: "Hardening During System Changes", description: "Bei jeder wesentlichen Systemänderung (Upgrade, Migration, neue Software) muss die Härtung überprüft und an die neue Konfiguration angepasst werden. Post-Change-Härtungsscans müssen durchgeführt werden. Der Change-Management-Prozess muss einen Härtungs-Checkpoint enthalten.", descriptionEn: "During every significant system change (upgrade, migration, new software), hardening must be verified and adapted to the new configuration. Post-change hardening scans must be conducted. The change management process must include a hardening checkpoint.", reason: "Systemänderungen können Härtungseinstellungen zurücksetzen oder neue Angriffsflächen einführen.", reasonEn: "System changes can reset hardening settings or introduce new attack surfaces.", whenRequired: "Bei jeder wesentlichen Systemänderung.", whenRequiredEn: "During every significant system change.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3", "CIS Controls v8 4.1"] },
  { id: "p18-c10", title: "Netzwerkdienst-Härtung", titleEn: "Network Service Hardening", description: "Alle netzwerkexponierten Dienste (Webserver, Mail-Server, DNS, Fileserver) müssen spezifisch gehärtet werden. HTTP-Security-Header müssen konfiguriert werden (HSTS, CSP, X-Frame-Options). TLS-Konfiguration muss den aktuellen BSI TR-02102 und Mozilla-Empfehlungen entsprechen. Server-Banner und Versionsinfos müssen unterdrückt werden.", descriptionEn: "All network-exposed services (web servers, mail servers, DNS, file servers) must be specifically hardened. HTTP security headers must be configured (HSTS, CSP, X-Frame-Options). TLS configuration must comply with current BSI TR-02102 and Mozilla recommendations. Server banners and version information must be suppressed.", reason: "Netzwerkexponierte Dienste sind direkt aus dem Internet erreichbar und damit besonders gefährdet.", reasonEn: "Network-exposed services are directly accessible from the internet and therefore particularly vulnerable.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz APP.3.1", "BSI TR-02102-2"] },
  { id: "p18-c11", title: "Kryptografische Härtung", titleEn: "Cryptographic Hardening", description: "Alle Systeme müssen nur aktuelle, sichere kryptografische Algorithmen und Protokolle verwenden. Veraltete Algorithmen (MD5, SHA-1, DES, RC4, TLS 1.0/1.1) müssen deaktiviert werden. Cipher-Suite-Prioritäten müssen Forward Secrecy bevorzugen. Die kryptografische Konfiguration muss mindestens jährlich gegen aktuelle Empfehlungen (BSI TR-02102, NIST SP 800-131A) geprüft werden. Diese Klausel behandelt die systemseitige Durchsetzung sicherer Kryptografie; die übergreifende Verschlüsselungsstrategie, Schlüsselmanagement und Zertifikatsverwaltung werden zentral in p23 — Verschlüsselungsrichtlinie definiert.", descriptionEn: "All systems must only use current, secure cryptographic algorithms and protocols. Deprecated algorithms (MD5, SHA-1, DES, RC4, TLS 1.0/1.1) must be disabled. Cipher suite priorities must prefer forward secrecy. Cryptographic configuration must be checked at least annually against current recommendations (BSI TR-02102, NIST SP 800-131A). This clause addresses system-level enforcement of secure cryptography; the overarching encryption strategy, key management, and certificate management are centrally defined in p23 — Encryption Policy.", reason: "Veraltete Kryptografie bietet keinen wirksamen Schutz und kann von Angreifern gebrochen werden.", reasonEn: "Deprecated cryptography provides no effective protection and can be broken by attackers.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.24", "BSI TR-02102", "NIST SP 800-131A", "ISO 27001:2022 A.8"] },
  { id: "p18-c12", title: "Protokollierungs-Härtung", titleEn: "Logging Hardening", description: "Audit-Protokollierung muss auf allen Systemen aktiviert und vor Manipulation geschützt werden. Logs müssen unverzüglich an einen zentralen Log-Server weitergeleitet werden. Lokale Logs müssen vor Löschung durch Angreifer geschützt werden (Write-Once-Speicher oder Append-Only-Konfiguration). Log-Rotation darf keine sicherheitsrelevanten Einträge löschen.", descriptionEn: "Audit logging must be enabled on all systems and protected against tampering. Logs must be immediately forwarded to a central log server. Local logs must be protected from deletion by attackers (write-once storage or append-only configuration). Log rotation must not delete security-relevant entries.", reason: "Ohne manipulationssichere Protokollierung können Angreifer ihre Spuren verwischen.", reasonEn: "Without tamper-proof logging, attackers can cover their tracks.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.15", "BSI IT-Grundschutz OPS.1.1.5", "CIS Controls v8 8.2"] },
  { id: "p18-c13", title: "Virtualisierungs-Härtung", titleEn: "Virtualisation Hardening", description: "Hypervisoren müssen nach Herstellervorgaben und CIS Benchmarks gehärtet werden. VM-Escape-Risiken müssen minimiert werden. Management-Interfaces müssen in separaten Netzwerksegmenten betrieben werden. Snapshots dürfen keine sensitiven Daten im Klartext enthalten. Inter-VM-Traffic muss kontrolliert werden.", descriptionEn: "Hypervisors must be hardened according to manufacturer guidelines and CIS Benchmarks. VM escape risks must be minimised. Management interfaces must operate in separate network segments. Snapshots must not contain sensitive data in cleartext. Inter-VM traffic must be controlled.", reason: "Ein kompromittierter Hypervisor gefährdet alle darauf laufenden virtuellen Maschinen.", reasonEn: "A compromised hypervisor endangers all virtual machines running on it.", whenRequired: "Erforderlich bei Virtualisierungseinsatz.", whenRequiredEn: "Required when using virtualisation.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz SYS.1.5", "CIS VMware Benchmarks"] },
  { id: "p18-c14", title: "Härtungsdokumentation und Ausnahmen", titleEn: "Hardening Documentation and Exceptions", description: "Alle Härtungsmaßnahmen und der aktuelle Härtungsstatus jedes Systems müssen dokumentiert werden. Abweichungen von der Baseline (Ausnahmen) müssen formal beantragt, risikobewert, genehmigt und zeitlich befristet werden. Ausnahmen müssen in einem zentralen Register erfasst und regelmäßig überprüft werden. Kompensierende Kontrollen müssen für jede Ausnahme definiert werden.", descriptionEn: "All hardening measures and the current hardening status of each system must be documented. Deviations from the baseline (exceptions) must be formally requested, risk-assessed, approved, and time-limited. Exceptions must be recorded in a central register and regularly reviewed. Compensating controls must be defined for each exception.", reason: "Undokumentierte Ausnahmen untergraben die Härtungsstrategie und schaffen unbekannte Risiken.", reasonEn: "Undocumented exceptions undermine the hardening strategy and create unknown risks.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz SYS.1.1", "CIS Controls v8 4.1"] },
  { id: "p18-c15", title: "Endpoint-Detection-Integration bei Härtung", titleEn: "Endpoint Detection Integration in Hardening", description: "Alle gehärteten Systeme müssen mit einer Endpoint Detection and Response (EDR)-Lösung ausgestattet werden. Die EDR-Konfiguration muss Manipulationsschutz (Tamper Protection) aktiviert haben. EDR-Agents müssen vor Deinstallation durch lokale Administratoren geschützt sein. Die EDR-Abdeckung muss als Härtungs-KPI überwacht werden. Diese Klausel definiert die EDR-Anforderung als Bestandteil der Härtungsstrategie für Server und Infrastruktursysteme; für endgerätespezifische EDR-Konfiguration, SIEM-Integration und Verhaltensanalyse siehe p17-c01 — Endpoint Detection and Response.", descriptionEn: "All hardened systems must be equipped with an Endpoint Detection and Response (EDR) solution. EDR configuration must have tamper protection enabled. EDR agents must be protected against uninstallation by local administrators. EDR coverage must be monitored as a hardening KPI. This clause defines the EDR requirement as part of the hardening strategy for servers and infrastructure systems; for endpoint-specific EDR configuration, SIEM integration, and behavioural analysis, see p17-c01 — Endpoint Detection and Response.", reason: "Härtung allein kann nicht alle Angriffe verhindern — EDR bietet die notwendige Erkennung und Reaktionsfähigkeit.", reasonEn: "Hardening alone cannot prevent all attacks — EDR provides the necessary detection and response capability.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.7", "BSI IT-Grundschutz OPS.1.1.4", "CIS Controls v8 13.7", "NIST CSF 2.0 DE.CM-01"] },
  { id: "p18-c16", title: "Firmware- und BIOS-Härtung", titleEn: "Firmware and BIOS Hardening", description: "BIOS/UEFI-Einstellungen müssen durch Administratorkennwörter geschützt werden. Firmware-Updates müssen in den Patch-Management-Prozess integriert werden. Firmware-Integritätsprüfungen müssen regelmäßig durchgeführt werden. Die Nutzung von Intel ME/AMD PSP muss bewertet und soweit möglich eingeschränkt werden.", descriptionEn: "BIOS/UEFI settings must be protected by administrator passwords. Firmware updates must be integrated into the patch management process. Firmware integrity checks must be performed regularly. Use of Intel ME/AMD PSP must be evaluated and restricted where possible.", reason: "Firmware-Angriffe sind besonders gefährlich, da sie unterhalb des Betriebssystems operieren und schwer zu erkennen sind.", reasonEn: "Firmware attacks are particularly dangerous as they operate below the operating system and are difficult to detect.", whenRequired: "Immer erforderlich für alle physischen Systeme.", whenRequiredEn: "Always required for all physical systems.", sources: ["BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 4.1", "NIST SP 800-147"] },
  { id: "p18-c17", title: "Server- und Infrastruktur-Applikations-Whitelisting", titleEn: "Server and Infrastructure Application Whitelisting", description: "Auf kritischen Servern und Infrastruktursystemen muss Application Whitelisting implementiert werden, um die Ausführung nicht autorisierter Software zu verhindern. Die Whitelist muss zentral verwaltet und regelmäßig aktualisiert werden. Ausnahmen müssen formal genehmigt und zeitlich befristet werden. Diese Klausel fokussiert auf Server- und Infrastruktursysteme; für Application Whitelisting auf Endgeräten (Workstations, Laptops) siehe p17-c05 — Application Whitelisting.", descriptionEn: "Application whitelisting must be implemented on critical servers and infrastructure systems to prevent the execution of unauthorised software. The whitelist must be centrally managed and regularly updated. Exceptions must be formally approved and time-limited. This clause focuses on server and infrastructure systems; for application whitelisting on endpoints (workstations, laptops), see p17-c05 — Application Whitelisting.", reason: "Application Whitelisting ist eine der wirksamsten Maßnahmen gegen Malware und unautorisierte Software auf Servern.", reasonEn: "Application whitelisting is one of the most effective measures against malware and unauthorised software on servers.", whenRequired: "Erforderlich für kritische Systeme und Server.", whenRequiredEn: "Required for critical systems and servers.", sources: ["ISO 27001:2022 A.8.19", "BSI IT-Grundschutz OPS.1.1.4", "CIS Controls v8 2.5", "NIST CSF 2.0 PR.PS-01"] },
  { id: "p18-c18", title: "Server- und Infrastruktur-Firewall-Härtung", titleEn: "Server and Infrastructure Firewall Hardening", description: "Auf allen Servern und Infrastruktursystemen muss eine Host-basierte Firewall aktiviert und nach dem Deny-All-Prinzip konfiguriert werden. Nur explizit benötigte ein- und ausgehende Verbindungen dürfen zugelassen werden. Die Firewall-Regeln müssen zentral verwaltet und regelmäßig überprüft werden. Diese Klausel fokussiert auf Server- und Infrastrukturebene; für Host-basierte Firewall-Anforderungen auf Endgeräten (Workstations, Laptops) siehe p17-c04 — Host-Based Firewall.", descriptionEn: "A host-based firewall must be enabled on all servers and infrastructure systems and configured according to the deny-all principle. Only explicitly required inbound and outbound connections may be permitted. Firewall rules must be centrally managed and regularly reviewed. This clause focuses on server and infrastructure level; for host-based firewall requirements on endpoints (workstations, laptops), see p17-c04 — Host-Based Firewall.", reason: "Die Host-basierte Firewall ist eine zusätzliche Verteidigungsschicht, die laterale Bewegung im Netzwerk erschwert.", reasonEn: "The host-based firewall is an additional defence layer that makes lateral movement in the network more difficult.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.22", "BSI IT-Grundschutz NET.3.2", "CIS Controls v8 4.4"] },
  { id: "p18-c19", title: "Härtung von Druckern und IoT-Geräten", titleEn: "Hardening of Printers and IoT Devices", description: "Netzwerkdrucker, Scanner und IoT-Geräte müssen in die Härtungsstrategie einbezogen werden. Standardkennwörter müssen geändert, nicht benötigte Dienste deaktiviert und Firmware aktuell gehalten werden. Diese Geräte müssen in ein separates Netzwerksegment isoliert werden.", descriptionEn: "Network printers, scanners, and IoT devices must be included in the hardening strategy. Default passwords must be changed, unnecessary services disabled, and firmware kept up to date. These devices must be isolated in a separate network segment.", reason: "IoT-Geräte und Drucker werden häufig als Einstiegspunkt für Angriffe übersehen.", reasonEn: "IoT devices and printers are frequently overlooked as entry points for attacks.", whenRequired: "Erforderlich wenn solche Geräte im Netzwerk vorhanden sind.", whenRequiredEn: "Required when such devices are present in the network.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz SYS.4.1", "CIS Controls v8 1.1", "NIST CSF 2.0 PR.PS-01"] },
  { id: "p18-c20", title: "Härtungs-Baseline-Versionierung", titleEn: "Hardening Baseline Versioning", description: "Alle Härtungs-Baselines müssen versioniert und in einem zentralen Repository verwaltet werden. Änderungen an Baselines müssen einem Change-Management-Prozess unterliegen und vor der Implementierung getestet werden. Detaillierte Anforderungen an Baseline-Versionierung, Änderungshistorie und Dokumentationsstandards werden in p19-c01 — Baseline Versioning and Change Management definiert.", descriptionEn: "All hardening baselines must be versioned and managed in a central repository. Changes to baselines must undergo a change management process and be tested before implementation. Detailed requirements for baseline versioning, change history, and documentation standards are defined in p19-c01 — Baseline Versioning and Change Management.", reason: "Versionierung ermöglicht Nachvollziehbarkeit und kontrollierte Änderungen an Sicherheitsstandards.", reasonEn: "Versioning enables traceability and controlled changes to security standards.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "CIS Controls v8 4.1", "BSI IT-Grundschutz OPS.1.1.3"] },
  { id: "p18-c21", title: "Automatisierte Härtungsdurchsetzung und Remediation", titleEn: "Automated Hardening Enforcement and Remediation", description: "Härtungseinstellungen müssen über Configuration-Management-Tools (Ansible, Puppet, Chef, Group Policy, Intune) automatisiert durchgesetzt werden. Abweichungen von der definierten Baseline müssen automatisch korrigiert werden (Auto-Remediation). Während p18-c08 die Prüfung und Erkennung von Abweichungen regelt, fokussiert diese Klausel auf die automatische Behebung und Durchsetzung. Für baseline-spezifische Drift-Erkennung und Konfigurationsmanagement-Integration siehe p19-c04.", descriptionEn: "Hardening settings must be automatically enforced via configuration management tools (Ansible, Puppet, Chef, Group Policy, Intune). Deviations from the defined baseline must be automatically corrected (auto-remediation). While p18-c08 governs verification and detection of deviations, this clause focuses on automatic remediation and enforcement. For baseline-specific drift detection and configuration management integration, see p19-c04.", reason: "Manuelle Härtung ist fehleranfällig und nicht skalierbar — automatisierte Durchsetzung stellt konsistente Sicherheit sicher.", reasonEn: "Manual hardening is error-prone and not scalable — automated enforcement ensures consistent security.", whenRequired: "Empfohlen für alle, erforderlich ab 100 Systemen.", whenRequiredEn: "Recommended for all, required for 100+ systems.", sources: ["ISO 27001:2022 A.8.9", "CIS Controls v8 4.2", "NIST CSF 2.0 PR.PS-01"] },
];

// ═══════════════════════════════════════════════════════════════
// P19 — Security Configuration Baseline Policy (20 clauses)
// ═══════════════════════════════════════════════════════════════
const p19: PolicyClause[] = [
  { id: "p19-c00", title: "Baseline-Definition und Geltungsbereich", titleEn: "Baseline Definition and Scope", description: "Die Organisation muss für jede Systemklasse (Windows-Server, Linux-Server, Workstations, Netzwerkgeräte, Datenbanken, Cloud-Instanzen, Container) eine Sicherheitskonfigurationsbaseline definieren. Die Baseline muss alle sicherheitsrelevanten Konfigurationsparameter umfassen und auf anerkannten Standards (CIS Benchmarks, BSI IT-Grundschutz) basieren.", descriptionEn: "The organisation must define a security configuration baseline for each system class (Windows servers, Linux servers, workstations, network devices, databases, cloud instances, containers). The baseline must encompass all security-relevant configuration parameters and be based on recognised standards (CIS Benchmarks, BSI IT-Grundschutz).", reason: "Ohne standardisierte Baselines variiert die Systemkonfiguration und das Sicherheitsniveau unkontrolliert.", reasonEn: "Without standardised baselines, system configuration and security levels vary uncontrollably.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz SYS.1.1", "CIS Controls v8 4.1"] },
  { id: "p19-c01", title: "Baseline-Versionierung und Änderungsmanagement", titleEn: "Baseline Versioning and Change Management", description: "Jede Baseline muss versioniert werden. Änderungen an Baselines müssen einem Change-Management-Prozess unterliegen. Jede Version muss dokumentiert werden mit: Datum, Autor, Änderungsbeschreibung, Begründung und Genehmigung. Die Versionshistorie muss lückenlos nachvollziehbar sein.", descriptionEn: "Each baseline must be versioned. Changes to baselines must be subject to a change management process. Each version must be documented with: date, author, change description, justification, and approval. Version history must be completely traceable.", reason: "Ohne Versionierung können Änderungen nicht nachverfolgt und bei Problemen nicht zurückgesetzt werden.", reasonEn: "Without versioning, changes cannot be tracked and rolled back when problems occur.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3"] },
  { id: "p19-c02", title: "Golden Image Management", titleEn: "Golden Image Management", description: "Für jede Systemklasse müssen gehärtete Referenz-Images (Golden Images) erstellt und gepflegt werden. Neue Systeme müssen von diesen Images bereitgestellt werden. Golden Images müssen regelmäßig aktualisiert werden (Patches, Baseline-Änderungen). Die Integrität der Images muss durch kryptografische Hashwerte sichergestellt werden.", descriptionEn: "For each system class, hardened reference images (golden images) must be created and maintained. New systems must be provisioned from these images. Golden images must be regularly updated (patches, baseline changes). Image integrity must be ensured through cryptographic hashes.", reason: "Golden Images stellen konsistente, sichere Ausgangskon­figurationen sicher und reduzieren die Bereitstellungszeit.", reasonEn: "Golden images ensure consistent, secure initial configurations and reduce provisioning time.", whenRequired: "Empfohlen für alle Organisationen, erforderlich bei standardisierter IT.", whenRequiredEn: "Recommended for all organisations, required for standardised IT.", sources: ["CIS Controls v8 4.2", "BSI IT-Grundschutz SYS.1.1", "NIST CSF 2.0 PR.PS-01"] },
  { id: "p19-c03", title: "Infrastructure as Code (IaC) Sicherheit", titleEn: "Infrastructure as Code (IaC) Security", description: "Wenn Infrastructure as Code verwendet wird, müssen IaC-Templates (Terraform, CloudFormation, Ansible, etc.) die definierten Sicherheitsbaselines implementieren. IaC-Code muss in Versionskontrollsystemen verwaltet und vor dem Deployment auf Sicherheitsverstöße gescannt werden (Policy as Code). Drift-Detection muss implementiert werden.", descriptionEn: "When Infrastructure as Code is used, IaC templates (Terraform, CloudFormation, Ansible, etc.) must implement defined security baselines. IaC code must be managed in version control systems and scanned for security violations before deployment (Policy as Code). Drift detection must be implemented.", reason: "IaC ermöglicht konsistente, wiederholbare und auditierbare Infrastrukturbereitstellung — aber nur wenn die Sicherheit im Code verankert ist.", reasonEn: "IaC enables consistent, repeatable, and auditable infrastructure provisioning — but only when security is embedded in the code.", whenRequired: "Erforderlich bei IaC-Nutzung.", whenRequiredEn: "Required when using IaC.", sources: ["ISO 27001:2022 A.8.9", "CIS Controls v8 4.1", "NIST CSF 2.0 PR.PS-01"] },
  { id: "p19-c04", title: "Konfigurations-Drift-Erkennung", titleEn: "Configuration Drift Detection", description: "Die Organisation muss Mechanismen implementieren, um Konfigurationsabweichungen (Drift) von der definierten Baseline automatisch zu erkennen. Drift-Erkennung muss kontinuierlich oder mindestens täglich stattfinden. Erkannte Abweichungen müssen automatisch gemeldet und nach Schweregrad priorisiert werden. Automatische Remediation sollte für unkritische Abweichungen implementiert werden. Diese Klausel ergänzt die härtungsspezifische Prüfung (p18-c08) und Durchsetzung (p18-c21) um eine konfigurationsmanagement-orientierte Perspektive mit Fokus auf Baseline-Konformität über den gesamten Systemlebenszyklus.", descriptionEn: "The organisation must implement mechanisms to automatically detect configuration deviations (drift) from the defined baseline. Drift detection must occur continuously or at least daily. Detected deviations must be automatically reported and prioritised by severity. Automatic remediation should be implemented for non-critical deviations. This clause complements hardening-specific verification (p18-c08) and enforcement (p18-c21) with a configuration-management-oriented perspective focusing on baseline conformity across the entire system lifecycle.", reason: "Konfigurationsdrift ist unvermeidlich und untergräbt die Härtung im Laufe der Zeit, wenn er nicht erkannt und behoben wird.", reasonEn: "Configuration drift is inevitable and undermines hardening over time if not detected and remediated.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "CIS Controls v8 4.1", "NIST CSF 2.0 DE.CM-09"] },
  { id: "p19-c05", title: "Baseline-Compliance-Messung", titleEn: "Baseline Compliance Measurement", description: "Der Compliance-Grad der Systeme gegenüber ihrer Baseline muss kontinuierlich gemessen und als KPI berichtet werden. Die Organisation muss einen Mindest-Compliance-Grad definieren (z.B. 95%). Systeme unter dem Mindest-Compliance-Grad müssen priorisiert behandelt werden. Trend-Analysen müssen durchgeführt werden.", descriptionEn: "The compliance degree of systems against their baseline must be continuously measured and reported as a KPI. The organisation must define a minimum compliance degree (e.g., 95%). Systems below the minimum compliance degree must be treated with priority. Trend analyses must be conducted.", reason: "Ohne messbare Compliance-Werte kann der Erfolg der Härtungsstrategie nicht bewertet werden.", reasonEn: "Without measurable compliance values, the success of the hardening strategy cannot be evaluated.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §9.1", "CIS Controls v8 4.1", "NIST CSF 2.0 ID.IM"] },
  { id: "p19-c06", title: "Baseline-Ausnahmemanagement", titleEn: "Baseline Exception Management", description: "Abweichungen von der Baseline müssen formal beantragt, risikobewert und genehmigt werden. Jede Ausnahme muss eine Begründung, kompensierende Kontrollen, einen Verantwortlichen und ein Ablaufdatum haben. Ausnahmen müssen regelmäßig überprüft und erneuert oder geschlossen werden. Ein zentrales Ausnahmeregister muss geführt werden.", descriptionEn: "Deviations from the baseline must be formally requested, risk-assessed, and approved. Each exception must have a justification, compensating controls, a responsible person, and an expiration date. Exceptions must be regularly reviewed and renewed or closed. A central exception register must be maintained.", reason: "Ausnahmen ohne formalen Prozess akkumulieren und schwächen die Sicherheitslage systematisch.", reasonEn: "Exceptions without a formal process accumulate and systematically weaken the security posture.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz", "CIS Controls v8 4.1"] },
  { id: "p19-c07", title: "Automatisierte Baseline-Deployment", titleEn: "Automated Baseline Deployment", description: "Baselines müssen automatisiert auf Systeme ausgerollt werden können — über Configuration-Management-Tools (Ansible, Puppet, Chef, Group Policy, Intune). Manuelle Konfiguration muss auf Ausnahmen beschränkt sein. Die automatisierte Bereitstellung muss idempotent sein und bei Fehlern detaillierte Logs erzeugen.", descriptionEn: "Baselines must be deployable to systems automatically — via configuration management tools (Ansible, Puppet, Chef, Group Policy, Intune). Manual configuration must be limited to exceptions. Automated provisioning must be idempotent and produce detailed logs on errors.", reason: "Manuelle Konfiguration ist fehleranfällig, nicht skalierbar und nicht reproduzierbar.", reasonEn: "Manual configuration is error-prone, not scalable, and not reproducible.", whenRequired: "Empfohlen für alle, erforderlich ab mittlerer Umgebungsgröße.", whenRequiredEn: "Recommended for all, required from medium environment size.", sources: ["CIS Controls v8 4.2", "BSI IT-Grundschutz SYS.1.1", "NIST CSF 2.0 PR.PS-01"] },
  { id: "p19-c08", title: "Baseline-Review und Aktualisierungszyklus", titleEn: "Baseline Review and Update Cycle", description: "Alle Baselines müssen mindestens halbjährlich und bei Veröffentlichung neuer Benchmark-Versionen überprüft und aktualisiert werden. Neue Bedrohungen, Schwachstellen und Herstellerempfehlungen müssen in die Baselines eingearbeitet werden. Der Review-Prozess muss dokumentiert werden.", descriptionEn: "All baselines must be reviewed and updated at least semi-annually and upon publication of new benchmark versions. New threats, vulnerabilities, and vendor recommendations must be incorporated into baselines. The review process must be documented.", reason: "Veraltete Baselines schützen nicht gegen neue Bedrohungen und Schwachstellen.", reasonEn: "Outdated baselines do not protect against new threats and vulnerabilities.", whenRequired: "Mindestens halbjährlich.", whenRequiredEn: "At least semi-annually.", sources: ["ISO 27001:2022 A.8.9", "CIS Controls v8 4.1"] },
  { id: "p19-c09", title: "Multi-Cloud-Baseline-Harmonisierung", titleEn: "Multi-Cloud Baseline Harmonisation", description: "Bei Nutzung mehrerer Cloud-Provider müssen die Sicherheitsbaselines harmonisiert werden, um ein einheitliches Schutzniveau sicherzustellen. Cloud-spezifische Benchmark-Empfehlungen (CIS AWS, Azure, GCP Benchmarks) müssen berücksichtigt werden. Ein übergreifendes Baseline-Framework muss die cloud-spezifischen Baselines zusammenführen.", descriptionEn: "When using multiple cloud providers, security baselines must be harmonised to ensure a uniform protection level. Cloud-specific benchmark recommendations (CIS AWS, Azure, GCP Benchmarks) must be considered. An overarching baseline framework must consolidate cloud-specific baselines.", reason: "Ohne Harmonisierung entstehen Sicherheitslücken durch unterschiedliche Schutzniveaus in verschiedenen Cloud-Umgebungen.", reasonEn: "Without harmonisation, security gaps arise from different protection levels in different cloud environments.", whenRequired: "Erforderlich bei Multi-Cloud-Nutzung.", whenRequiredEn: "Required for multi-cloud usage.", sources: ["BSI C5:2020", "CIS Cloud Benchmarks", "ISO 27001:2022 A.8.9"] },
  { id: "p19-c10", title: "Compliance-Reporting und Dashboards", titleEn: "Compliance Reporting and Dashboards", description: "Baseline-Compliance-Daten müssen in Echtzeit-Dashboards visualisiert werden, die den aktuellen Compliance-Status nach Systemklasse, Geschäftsbereich und Kritikalität darstellen. Monatliche Compliance-Reports müssen der IT-Sicherheitsleitung vorgelegt werden. Trend-Analysen müssen die Entwicklung des Compliance-Grads über die Zeit zeigen.", descriptionEn: "Baseline compliance data must be visualised in real-time dashboards showing current compliance status by system class, business unit, and criticality. Monthly compliance reports must be presented to IT security management. Trend analyses must show the evolution of compliance degree over time.", reason: "Transparente Berichterstattung ermöglicht fundierte Entscheidungen und erhöht die Aufmerksamkeit des Managements.", reasonEn: "Transparent reporting enables informed decisions and increases management attention.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §9.1", "NIST CSF 2.0 ID.IM"] },
  { id: "p19-c11", title: "Netzwerkgeräte-Baseline", titleEn: "Network Device Baseline", description: "Für alle Netzwerkgeräte (Router, Switches, Firewalls, Load Balancer, WLAN-Controller) müssen spezifische Sicherheitsbaselines definiert werden. Diese müssen umfassen: sichere Managementprotokolle, Zugriffskontrolllisten, NTP-Konfiguration, Logging-Konfiguration, SNMP-Härtung, Banner-Konfiguration und unnötige Dienste-Deaktivierung.", descriptionEn: "Specific security baselines must be defined for all network devices (routers, switches, firewalls, load balancers, WLAN controllers). These must include: secure management protocols, access control lists, NTP configuration, logging configuration, SNMP hardening, banner configuration, and unnecessary service deactivation.", reason: "Netzwerkgeräte bilden das Rückgrat der IT-Infrastruktur und müssen ebenso gehärtet werden wie Server und Endgeräte.", reasonEn: "Network devices form the backbone of IT infrastructure and must be hardened just like servers and endpoints.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["BSI IT-Grundschutz NET.3.1", "CIS Network Device Benchmarks", "CIS Controls v8 4.1"] },
  { id: "p19-c12", title: "Baseline-Test und Validierung", titleEn: "Baseline Testing and Validation", description: "Neue oder aktualisierte Baselines müssen vor dem Produktionsrollout in einer Testumgebung validiert werden. Tests müssen sicherstellen, dass die Baseline keine betriebskritischen Funktionen beeinträchtigt. Funktions- und Sicherheitstests müssen dokumentiert werden. Ein stufenweiser Rollout (Pilot → Produktion) muss verfolgt werden.", descriptionEn: "New or updated baselines must be validated in a test environment before production rollout. Tests must ensure the baseline does not impair business-critical functions. Functional and security tests must be documented. A phased rollout (pilot → production) must be followed.", reason: "Ungetestete Baselines können zu Systemausfällen und Betriebsunterbrechungen führen.", reasonEn: "Untested baselines can lead to system failures and operational disruptions.", whenRequired: "Vor jedem Baseline-Rollout.", whenRequiredEn: "Before every baseline rollout.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3"] },
  { id: "p19-c13", title: "Secure-by-Default-Prinzip", titleEn: "Secure-by-Default Principle", description: "Alle Systeme müssen standardmäßig sicher konfiguriert sein. Die sichere Konfiguration ist der Ausgangszustand; Lockerungen der Sicherheit müssen explizit begründet und genehmigt werden. Hersteller-Standardkonfigurationen dürfen nicht ohne Härtung in Produktion genommen werden.", descriptionEn: "All systems must be securely configured by default. The secure configuration is the starting state; relaxations of security must be explicitly justified and approved. Manufacturer default configurations must not be put into production without hardening.", reason: "Unsichere Standardkonfigurationen sind eine der häufigsten Ursachen für Sicherheitsvorfälle.", reasonEn: "Insecure default configurations are one of the most common causes of security incidents.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.9", "CIS Controls v8 4.1", "NIST CSF 2.0 PR.PS-01"] },
  { id: "p19-c14", title: "Endbenutzer-Konfigurationsbeschränkungen", titleEn: "End-User Configuration Restrictions", description: "Endbenutzer dürfen keine sicherheitsrelevanten Systemkonfigurationen ändern. Group Policy, MDM oder vergleichbare Mechanismen müssen sicherstellen, dass Benutzer keine Firewall deaktivieren, Antivirus-Software deinstallieren, USB-Richtlinien umgehen oder andere Sicherheitseinstellungen verändern können. Für die Einschränkung lokaler Administratorrechte auf Endgeräten und Privilege-Elevation-Prozesse siehe p17-c11 — Lokale Administratorrechte.", descriptionEn: "End users must not be able to change security-relevant system configurations. Group Policy, MDM, or comparable mechanisms must ensure users cannot disable firewalls, uninstall antivirus software, bypass USB policies, or modify other security settings. For restriction of local administrator rights on endpoints and privilege elevation processes, see p17-c11 — Local Administrator Rights.", reason: "Benutzer, die Sicherheitseinstellungen verändern können, gefährden nicht nur ihr eigenes Gerät, sondern das gesamte Netzwerk.", reasonEn: "Users who can change security settings endanger not only their own device but the entire network.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.2", "BSI IT-Grundschutz SYS.2.1", "CIS Controls v8 4.5"] },
  { id: "p19-c15", title: "Patch-Status als Baseline-Element", titleEn: "Patch Status as Baseline Element", description: "Der aktuelle Patch-Status ist integraler Bestandteil der Sicherheitsbaseline. Systeme mit überfälligen Sicherheitspatches gelten als nicht baseline-konform. Die Baseline-Compliance-Messung muss den Patch-Status einschließen.", descriptionEn: "Current patch status is an integral part of the security baseline. Systems with overdue security patches are considered non-baseline-compliant. Baseline compliance measurement must include patch status.", reason: "Eine gehärtete Konfiguration ohne aktuelle Patches bietet keinen vollständigen Schutz.", reasonEn: "A hardened configuration without current patches does not provide complete protection.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "CIS Controls v8 7.4"] },
  { id: "p19-c16", title: "Applikations-Baselines", titleEn: "Application Baselines", description: "Neben Betriebssystem-Baselines müssen auch Sicherheitsbaselines für kritische Anwendungen definiert werden — ERP-Systeme, Datenbanken, E-Mail-Server, Collaboration-Tools. Diese müssen anwendungsspezifische Sicherheitskonfigurationen abdecken: Berechtigungsmodell, Audit-Logging, Verschlüsselung, API-Sicherheit.", descriptionEn: "In addition to operating system baselines, security baselines must also be defined for critical applications — ERP systems, databases, email servers, collaboration tools. These must cover application-specific security configurations: permission model, audit logging, encryption, API security.", reason: "Anwendungen haben eigene Sicherheitskonfigurationen, die unabhängig vom Betriebssystem gehärtet werden müssen.", reasonEn: "Applications have their own security configurations that must be hardened independently of the operating system.", whenRequired: "Erforderlich für kritische Anwendungen.", whenRequiredEn: "Required for critical applications.", sources: ["ISO 27001:2022 A.8.9", "BSI IT-Grundschutz APP", "CIS Application Benchmarks"] },
  { id: "p19-c17", title: "Zeitquelle und NTP-Härtung", titleEn: "Time Source and NTP Hardening", description: "Alle Systeme müssen ihre Zeit von vertrauenswürdigen, gehärteten NTP-Servern synchronisieren. NTP-Authentifizierung muss verwendet werden. Die Zeitabweichung darf maximal 1 Sekunde betragen. Konsistente Zeitsynchronisation ist Voraussetzung für korrekte Log-Korrelation und forensische Analyse.", descriptionEn: "All systems must synchronise their time from trusted, hardened NTP servers. NTP authentication must be used. Time deviation must not exceed 1 second. Consistent time synchronisation is a prerequisite for correct log correlation and forensic analysis.", reason: "Ohne konsistente Zeitquelle ist die Korrelation von Sicherheitsereignissen über verschiedene Systeme hinweg unmöglich.", reasonEn: "Without a consistent time source, correlation of security events across different systems is impossible.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.17", "BSI IT-Grundschutz OPS.1.1.5", "CIS Controls v8 8.4"] },
  { id: "p19-c18", title: "Compliance-Integration in CI/CD", titleEn: "Compliance Integration in CI/CD", description: "Baseline-Compliance-Prüfungen müssen in die CI/CD-Pipeline integriert werden, sodass nur konforme Konfigurationen deployed werden. Policy-as-Code-Tools (Open Policy Agent, Sentinel, Conftest) müssen Konfigurationsänderungen vor dem Deployment validieren. Nicht-konforme Deployments müssen blockiert werden.", descriptionEn: "Baseline compliance checks must be integrated into the CI/CD pipeline so that only compliant configurations are deployed. Policy-as-Code tools (Open Policy Agent, Sentinel, Conftest) must validate configuration changes before deployment. Non-compliant deployments must be blocked.", reason: "Shift-Left-Security verhindert, dass nicht-konforme Konfigurationen in die Produktion gelangen.", reasonEn: "Shift-left security prevents non-compliant configurations from reaching production.", whenRequired: "Erforderlich bei CI/CD-Nutzung.", whenRequiredEn: "Required when using CI/CD.", sources: ["CIS Controls v8 4.1", "NIST CSF 2.0 PR.PS-01", "DevSecOps Best Practices"] },
  { id: "p19-c19", title: "Disaster Recovery Baseline-Wiederherstellung", titleEn: "Disaster Recovery Baseline Restoration", description: "Im Disaster-Recovery-Fall müssen wiederhergestellte Systeme automatisch die aktuelle Sicherheitsbaseline erhalten. DR-Prozeduren müssen sicherstellen, dass nach einer Wiederherstellung keine unsicheren Konfigurationen bestehen. Post-Recovery-Baseline-Scans müssen verpflichtend durchgeführt werden. Die übergreifenden Disaster-Recovery-Prozesse, RTO/RPO-Anforderungen und Wiederherstellungsreihenfolgen werden in p35 — Disaster Recovery Policy definiert; diese Klausel fokussiert auf die Baseline-Konformität wiederhergestellter Systeme.", descriptionEn: "In disaster recovery scenarios, restored systems must automatically receive the current security baseline. DR procedures must ensure no insecure configurations exist after restoration. Post-recovery baseline scans must be mandatory. Overarching disaster recovery processes, RTO/RPO requirements, and recovery sequences are defined in p35 — Disaster Recovery Policy; this clause focuses on baseline conformity of restored systems.", reason: "Wiederhergestellte Systeme mit veralteten oder unsicheren Konfigurationen schaffen neue Schwachstellen.", reasonEn: "Restored systems with outdated or insecure configurations create new vulnerabilities.", whenRequired: "Erforderlich bei DR-Szenarien.", whenRequiredEn: "Required for DR scenarios.", sources: ["ISO 22301:2019 §8.4", "BSI-Standard 200-4", "CIS Controls v8 4.1"] },
];

// ═══════════════════════════════════════════════════════════════
// P20 — Malware Protection Policy (20 clauses)
// ═══════════════════════════════════════════════════════════════
const p20: PolicyClause[] = [
  { id: "p20-c00", title: "Anti-Malware-Strategie", titleEn: "Anti-Malware Strategy", description: "Die Organisation muss eine mehrschichtige Anti-Malware-Strategie implementieren, die Prävention, Erkennung und Reaktion kombiniert. Die Strategie muss alle Bedrohungsvektoren abdecken: E-Mail, Web, Wechselmedien, Netzwerk und Insider. Signaturbasierte, verhaltensbasierte und KI-gestützte Erkennung müssen kombiniert werden.", descriptionEn: "The organisation must implement a multi-layered anti-malware strategy combining prevention, detection, and response. The strategy must cover all threat vectors: email, web, removable media, network, and insider. Signature-based, behaviour-based, and AI-powered detection must be combined.", reason: "Einzelne Anti-Malware-Technologien können von fortgeschrittenen Bedrohungen umgangen werden; nur ein mehrschichtiger Ansatz bietet angemessenen Schutz.", reasonEn: "Individual anti-malware technologies can be bypassed by advanced threats; only a multi-layered approach provides adequate protection.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.7", "ISO 27001:2022 A.8", "BSI IT-Grundschutz OPS.1.1.4", "CIS Controls v8 10"] },
  { id: "p20-c01", title: "Endpoint-Malware-Schutz", titleEn: "Endpoint Malware Protection", description: "Auf allen Endgeräten und Servern muss eine Endpoint-Protection-Lösung installiert sein, die Echtzeit-Scanning, On-Access-Scanning und On-Demand-Scanning bietet. Die Lösung muss Malware automatisch quarantänisieren oder entfernen. Anti-Tamper-Schutz muss aktiviert sein. Hinweis: Die allgemeine Endpoint-Compliance und EDR-Plattformverwaltung wird in p17 geregelt; diese Klausel fokussiert auf die Malware-spezifische Konfiguration und Erkennungsleistung.", descriptionEn: "An endpoint protection solution must be installed on all endpoints and servers providing real-time scanning, on-access scanning, and on-demand scanning. The solution must automatically quarantine or remove malware. Anti-tamper protection must be enabled. Note: General endpoint compliance and EDR platform management is governed by p17; this clause focuses on malware-specific configuration and detection performance.", reason: "Ohne Echtzeit-Schutz auf jedem Endgerät ist die Organisation einzelnen Infektionen schutzlos ausgeliefert.", reasonEn: "Without real-time protection on every endpoint, the organisation is defenceless against individual infections.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.7", "BSI IT-Grundschutz OPS.1.1.4", "CIS Controls v8 10.1"] },
  { id: "p20-c02", title: "Signatur- und Definition-Updates", titleEn: "Signature and Definition Updates", description: "Malware-Signaturen und -Definitionen müssen automatisch und mindestens stündlich aktualisiert werden. Die Organisation muss den Aktualisierungsstatus aller Endgeräte zentral überwachen. Geräte mit veralteten Signaturen (>24h) müssen als nicht-konform markiert und priorisiert aktualisiert werden.", descriptionEn: "Malware signatures and definitions must be updated automatically and at least hourly. The organisation must centrally monitor the update status of all endpoints. Devices with outdated signatures (>24h) must be flagged as non-compliant and updated with priority.", reason: "Veraltete Signaturen können aktuelle Malware nicht erkennen.", reasonEn: "Outdated signatures cannot detect current malware.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.7", "BSI IT-Grundschutz OPS.1.1.4", "CIS Controls v8 10.2"] },
  { id: "p20-c03", title: "E-Mail-Malware-Schutz", titleEn: "Email Malware Protection", description: "E-Mail-Gateways müssen alle eingehenden und ausgehenden E-Mails auf Malware scannen. Gefährliche Anhangtypen müssen standardmäßig blockiert werden. Sandboxing für verdächtige Anhänge muss implementiert werden. URL-Rewriting und Link-Time-Scanning müssen aktiv sein.", descriptionEn: "Email gateways must scan all incoming and outgoing emails for malware. Dangerous attachment types must be blocked by default. Sandboxing for suspicious attachments must be implemented. URL rewriting and link-time scanning must be active.", reason: "E-Mail ist der primäre Verbreitungsweg für Malware und Phishing.", reasonEn: "Email is the primary distribution channel for malware and phishing.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.7", "BSI IT-Grundschutz APP.5.3", "CIS Controls v8 9.7"] },
  { id: "p20-c04", title: "Web-Content-Filtering", titleEn: "Web Content Filtering", description: "Web-Proxy oder DNS-basiertes Content-Filtering muss den Zugang zu bekannten bösartigen Websites, Phishing-Seiten und potenziell unerwünschten Kategorien blockieren. Downloads müssen auf Malware gescannt werden. SSL/TLS-Inspektion sollte für Web-Traffic implementiert werden (unter Berücksichtigung datenschutzrechtlicher Anforderungen).", descriptionEn: "Web proxy or DNS-based content filtering must block access to known malicious websites, phishing sites, and potentially unwanted categories. Downloads must be scanned for malware. SSL/TLS inspection should be implemented for web traffic (considering data protection requirements).", reason: "Webbasierte Angriffe sind ein häufiger Infektionsweg.", reasonEn: "Web-based attacks are a common infection vector.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.23", "BSI IT-Grundschutz APP.1.2", "CIS Controls v8 9.2"] },
  { id: "p20-c05", title: "Sandbox-Analyse", titleEn: "Sandbox Analysis", description: "Verdächtige Dateien und E-Mail-Anhänge müssen in einer Sandbox-Umgebung detoniert und analysiert werden, bevor sie dem Benutzer zugestellt werden. Die Sandbox muss verschiedene Betriebssystem- und Anwendungsversionen simulieren. Sandbox-Ergebnisse müssen in die Bedrohungsintelligenz integriert werden.", descriptionEn: "Suspicious files and email attachments must be detonated and analysed in a sandbox environment before delivery to the user. The sandbox must simulate various OS and application versions. Sandbox results must be integrated into threat intelligence.", reason: "Sandboxing erkennt Zero-Day-Malware und polymorphe Bedrohungen, die signaturbasierte Erkennung umgehen.", reasonEn: "Sandboxing detects zero-day malware and polymorphic threats that bypass signature-based detection.", whenRequired: "Empfohlen für alle, erforderlich für kritische Umgebungen.", whenRequiredEn: "Recommended for all, required for critical environments.", sources: ["BSI IT-Grundschutz OPS.1.1.4", "NIST CSF 2.0 DE.CM-01", "CIS Controls v8 10.4"] },
  { id: "p20-c06", title: "Ransomware-spezifische Gegenmaßnahmen", titleEn: "Ransomware-Specific Countermeasures", description: "Die Organisation muss spezifische Gegenmaßnahmen gegen Ransomware implementieren: Controlled Folder Access, regelmäßige Offline-/Air-Gapped-Backups (Details siehe p36), Einschränkung von LOLBins, Honey-Files/Canary-Tokens zur Früherkennung, Netzwerksegmentierung zur Begrenzung der Ausbreitung (koordiniert mit p16), und Deception Technology.", descriptionEn: "The organisation must implement specific countermeasures against ransomware: Controlled Folder Access, regular offline/air-gapped backups (details see p36), restriction of LOLBins, honey files/canary tokens for early detection, network segmentation to limit spread (coordinated with p16), and deception technology.", reason: "Ransomware ist die finanziell schädlichste Malware-Kategorie.", reasonEn: "Ransomware is the most financially damaging malware category.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.7", "BSI IT-Grundschutz OPS.1.1.4", "ISO 27001:2022 A.5.24-28", "NIST CSF 2.0 PR.PS"] },
  { id: "p20-c07", title: "Malware-Vorfallbehandlung", titleEn: "Malware Incident Handling", description: "Die Organisation muss spezifische Verfahren für die Behandlung von Malware-Vorfällen definieren: automatische Isolierung infizierter Systeme, forensische Sicherung, Eindämmung, Bereinigung, Wiederherstellung und Post-Incident-Analyse. Eskalationskriterien und Kommunikationswege müssen definiert sein (koordiniert mit p31 Incident Reporting und p32 Incident Response). Die Ausbreitungsanalyse muss Priorität haben.", descriptionEn: "The organisation must define specific procedures for handling malware incidents: automatic isolation of infected systems, forensic preservation, containment, cleaning, restoration, and post-incident analysis. Escalation criteria and communication channels must be defined (coordinated with p31 Incident Reporting and p32 Incident Response). Spread analysis must have priority.", reason: "Schnelle und strukturierte Reaktion begrenzt den Schaden erheblich.", reasonEn: "Rapid and structured response significantly limits damage.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.24", "BSI IT-Grundschutz DER.2.1", "ISO 27001:2022 A.5.24-28"] },
  { id: "p20-c08", title: "Threat Intelligence Integration", titleEn: "Threat Intelligence Integration", description: "Die Anti-Malware-Infrastruktur muss mit Threat-Intelligence-Feeds integriert werden. Indicators of Compromise (IoCs) müssen automatisch in Sicherheitstools eingespielt werden. Die Organisation muss mindestens kommerzielle und Open-Source-Feeds nutzen (MISP, AlienVault OTX, Branchenspezifische ISACs).", descriptionEn: "The anti-malware infrastructure must be integrated with threat intelligence feeds. Indicators of Compromise (IoCs) must be automatically ingested into security tools. The organisation must use at least commercial and open-source feeds (MISP, AlienVault OTX, sector-specific ISACs).", reason: "Threat Intelligence ermöglicht proaktive Abwehr bekannter Bedrohungen.", reasonEn: "Threat intelligence enables proactive defence against known threats.", whenRequired: "Empfohlen für alle, erforderlich für kritische Infrastrukturen.", whenRequiredEn: "Recommended for all, required for critical infrastructures.", sources: ["ISO 27001:2022 A.5.7", "ISO 27001:2022 A.5.6", "NIST CSF 2.0 ID.RA-02"] },
  { id: "p20-c09", title: "Malware-spezifische Benutzer-Sensibilisierung", titleEn: "Malware-Specific User Awareness", description: "Benutzer müssen gezielt über aktuelle Malware-Bedrohungen, Erkennungsmerkmale verdächtiger Dateien und E-Mails sowie das korrekte Meldeverfahren (z.B. Phishing-Report-Button) geschult werden. Phishing-Simulationen müssen mindestens vierteljährlich durchgeführt werden. Hinweis: Die übergreifende Sicherheits-Awareness-Strategie wird in p44/p45 geregelt; diese Klausel adressiert ausschließlich malware-spezifische Inhalte.", descriptionEn: "Users must be specifically trained on current malware threats, recognition of suspicious files and emails, and correct reporting procedures. Phishing simulations must be conducted at least quarterly. Note: The overarching security awareness strategy is governed by p44/p45; this clause addresses exclusively malware-specific content.", reason: "Die menschliche Komponente bleibt die größte Schwachstelle bei Malware-Angriffen.", reasonEn: "The human component remains the greatest vulnerability in malware attacks.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.6.3", "ISO 27001:2022 §7.2", "BSI IT-Grundschutz ORP.3", "CIS Controls v8 14"] },
  { id: "p20-c10", title: "Fileless Malware-Schutz", titleEn: "Fileless Malware Protection", description: "Die Organisation muss Schutzmaßnahmen gegen dateilose Malware implementieren: AMSI-Integration, Memory-Protection-Mechanismen, Einschränkung von PowerShell und WMI, Verhaltensanalyse durch EDR, und Monitoring von Process-Injection-Techniken.", descriptionEn: "The organisation must implement protection measures against fileless malware: AMSI integration, memory protection mechanisms, restriction of PowerShell and WMI, behavioural analysis through EDR, and monitoring of process injection techniques.", reason: "Fileless Malware umgeht traditionelle dateibasierte Scans.", reasonEn: "Fileless malware bypasses traditional file-based scans.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["CIS Controls v8 10.7", "BSI IT-Grundschutz OPS.1.1.4", "NIST CSF 2.0 DE.CM-01"] },
  { id: "p20-c11", title: "Mobile Malware-Schutz", titleEn: "Mobile Malware Protection", description: "Mobile Endgeräte müssen gegen mobile Malware geschützt werden. Mobile Threat Defense (MTD) Lösungen müssen auf verwalteten Geräten installiert sein. App-Installation muss auf genehmigte Stores beschränkt werden. Jailbreak-/Root-Detection muss implementiert werden.", descriptionEn: "Mobile devices must be protected against mobile malware. MTD solutions must be installed on managed devices. App installation must be restricted to approved stores. Jailbreak/root detection must be implemented.", reason: "Mobile Geräte sind zunehmend Ziel von Malware.", reasonEn: "Mobile devices are increasingly targeted by malware.", whenRequired: "Erforderlich bei mobiler Gerätenutzung.", whenRequiredEn: "Required when using mobile devices.", sources: ["ISO 27001:2022 A.8.1", "BSI IT-Grundschutz SYS.3.2.1", "CIS Controls v8 10.5"] },
  { id: "p20-c12", title: "Server-seitige Malware-Prüfung", titleEn: "Server-Side Malware Scanning", description: "Dateiserver, Webserver, E-Mail-Server und Anwendungsserver müssen über serverseitigen Malware-Schutz verfügen. Hochgeladene Dateien müssen vor der Verarbeitung oder Speicherung gescannt werden.", descriptionEn: "File servers, web servers, email servers, and application servers must have server-side malware protection. Uploaded files must be scanned before processing or storage.", reason: "Server können als Multiplikatoren für Malware-Verbreitung dienen.", reasonEn: "Servers can serve as multipliers for malware distribution.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.7", "BSI IT-Grundschutz OPS.1.1.4", "CIS Controls v8 10.1"] },
  { id: "p20-c13", title: "Malware-Analyse und Forensik", titleEn: "Malware Analysis and Forensics", description: "Die Organisation muss Fähigkeiten zur Malware-Analyse aufbauen oder Zugang zu externen Analysediensten haben. Erfasste Malware-Samples müssen sicher aufbewahrt und analysiert werden. Ergebnisse müssen zur Verbesserung der Erkennungsmaßnahmen verwendet werden.", descriptionEn: "The organisation must build malware analysis capabilities or have access to external analysis services. Captured malware samples must be securely stored and analysed. Results must be used to improve detection measures.", reason: "Malware-Analyse ermöglicht das Verständnis von Angriffstechniken.", reasonEn: "Malware analysis enables understanding of attack techniques.", whenRequired: "Empfohlen für alle, erforderlich für kritische Infrastrukturen.", whenRequiredEn: "Recommended for all, required for critical infrastructures.", sources: ["ISO 27001:2022 A.5.7", "BSI IT-Grundschutz DER.2.2", "NIST CSF 2.0 RS.AN"] },
  { id: "p20-c14", title: "Anti-Malware-Reporting und KPIs", titleEn: "Anti-Malware Reporting and KPIs", description: "Die Organisation muss KPIs für den Malware-Schutz definieren und monatlich berichten: Anzahl erkannter/blockierter Malware, Infektionsrate, Time-to-Detection, Time-to-Containment, Signatur-Aktualisierungsrate, Phishing-Klickrate.", descriptionEn: "The organisation must define anti-malware KPIs and report monthly: number of detected/blocked malware, infection rate, time-to-detection, time-to-containment, signature update rate, phishing click rate.", reason: "Ohne KPIs kann die Effektivität nicht objektiv bewertet werden.", reasonEn: "Without KPIs, effectiveness cannot be objectively assessed.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §9.1", "NIST CSF 2.0 ID.IM"] },
  { id: "p20-c15", title: "Supply-Chain-Malware-Tarama", titleEn: "Supply Chain Malware Scanning", description: "Software und Updates von Drittanbietern müssen vor dem Deployment auf Malware und Manipulationen geprüft werden. Code-Signing-Validierung muss für alle Software-Installationen erzwungen werden. Hinweis: Die SBOM-Erstellung und -Pflege wird in p47 (Secure Development) geregelt; die allgemeine Lieferantensicherheit in p42.", descriptionEn: "Software and updates from third parties must be checked for malware and tampering before deployment. Code signing validation must be enforced. Note: SBOM creation and maintenance is governed by p47 (Secure Development); general supplier security by p42.", reason: "Supply-Chain-Angriffe nutzen das Vertrauen in Lieferanten aus.", reasonEn: "Supply chain attacks exploit trust in suppliers.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.19-23", "ISO 27001:2022 A.5.21", "NIST CSF 2.0 GV.SC", "CIS Controls v8 16.9"] },
  { id: "p20-c16", title: "Netzwerk-Malware-Erkennung", titleEn: "Network Malware Detection", description: "Netzwerk-basierte Malware-Erkennung muss an kritischen Netzwerkübergängen implementiert werden (Deep Packet Inspection, Netzwerk-Sandboxing). Erkannte Bedrohungen müssen automatisch blockiert und an das SOC gemeldet werden. Hinweis: Allgemeine IDS/IPS wird in p16-c04, NDR in p16-c10 geregelt; diese Klausel adressiert malware-spezifische Netzwerkanalyse.", descriptionEn: "Network-based malware detection must be implemented at critical network boundaries (DPI, network sandboxing). Detected threats must be automatically blocked and reported to the SOC. Note: General IDS/IPS is governed by p16-c04, NDR by p16-c10; this clause addresses malware-specific network analysis.", reason: "Netzwerk-basierte Erkennung bietet eine zusätzliche Verteidigungsschicht.", reasonEn: "Network-based detection provides an additional defence layer.", whenRequired: "Empfohlen für alle, erforderlich für kritische Netzwerke.", whenRequiredEn: "Recommended for all, required for critical networks.", sources: ["ISO 27001:2022 A.8.16", "BSI IT-Grundschutz NET.3.4", "NIST CSF 2.0 DE.CM-01"] },
  { id: "p20-c17", title: "Malware-Übungen und Simulationen", titleEn: "Malware Exercises and Simulations", description: "Die Organisation muss regelmäßig Malware-Szenarien simulieren: Red-Team-Übungen, Tabletop-Szenarien für Ransomware-Vorfälle, Phishing-Kampagnen und Purple-Team-Assessments. Ergebnisse müssen dokumentiert und Verbesserungsmaßnahmen abgeleitet werden.", descriptionEn: "The organisation must regularly simulate malware scenarios: red team exercises, tabletop scenarios for ransomware incidents, phishing campaigns, and purple team assessments. Results must be documented and improvement measures derived.", reason: "Ohne regelmäßige Übungen ist die Reaktionsfähigkeit im Ernstfall unzureichend.", reasonEn: "Without regular exercises, response capability in real incidents is insufficient.", whenRequired: "Mindestens jährlich.", whenRequiredEn: "At least annually.", sources: ["ISO 27001:2022 A.5.24", "ISO 27001:2022 A.5.29-30", "BSI IT-Grundschutz DER.4"] },
  { id: "p20-c18", title: "Quarantäne-Management", titleEn: "Quarantine Management", description: "Erkannte Malware muss automatisch quarantänisiert werden. Quarantänisierte Dateien müssen regelmäßig überprüft und nach definierter Frist gelöscht werden. Die Freigabe quarantänisierter Dateien (False Positives) muss einem Genehmigungsprozess unterliegen.", descriptionEn: "Detected malware must be automatically quarantined. Quarantined files must be regularly reviewed and deleted after a defined period. Release of quarantined files (false positives) must be subject to an approval process.", reason: "Effektives Quarantäne-Management verhindert erneute Infektion.", reasonEn: "Effective quarantine management prevents reinfection.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.7", "BSI IT-Grundschutz OPS.1.1.4"] },
  { id: "p20-c19", title: "Zero-Trust-Ausführungskontrolle", titleEn: "Zero Trust Execution Control", description: "Die Organisation sollte einen Zero-Trust-Ansatz für die Software-Ausführung verfolgen: nur explizit vertrauenswürdige Software darf ausgeführt werden (Code-Signing, Application Whitelisting, Reputation-Scoring). Unbekannte Binaries müssen in einer Sandbox analysiert werden. Hinweis: Das Ausnahmemanagement für Anwendungskontrollrichtlinien wird in p18 (System Hardening) geregelt.", descriptionEn: "The organisation should pursue a zero trust approach for software execution: only explicitly trusted software may execute (code signing, application whitelisting, reputation scoring). Unknown binaries must be analysed in a sandbox. Note: Exception management for application control policies is governed by p18 (System Hardening).", reason: "Zero-Trust-Ausführungskontrolle bietet den höchsten Schutz gegen unbekannte Malware.", reasonEn: "Zero trust execution control provides the highest protection against unknown malware.", whenRequired: "Empfohlen für alle, erforderlich für hochsichere Umgebungen.", whenRequiredEn: "Recommended for all, required for high-security environments.", sources: ["NIST SP 800-207", "CIS Controls v8 2.5", "BSI IT-Grundschutz SYS.2.1"] },
];

// ═══════════════════════════════════════════════════════════════
// P21 — Vulnerability Management Policy (25 clauses)
// ═══════════════════════════════════════════════════════════════
const p21: PolicyClause[] = [
  { id: "p21-c00", title: "Schwachstellenmanagement-Programm", titleEn: "Vulnerability Management Programme", description: "Die Organisation muss ein formalisiertes Schwachstellenmanagement-Programm betreiben, das den gesamten Lebenszyklus von Schwachstellen abdeckt: Identifikation, Bewertung, Priorisierung, Behandlung, Verifizierung und Berichterstattung. Das Programm muss alle IT-Assets abdecken.", descriptionEn: "The organisation must operate a formalised vulnerability management programme covering the entire vulnerability lifecycle: identification, assessment, prioritisation, treatment, verification, and reporting. The programme must cover all IT assets.", reason: "Unbehandelte Schwachstellen sind die häufigste Ursache für erfolgreiche Cyber-Angriffe.", reasonEn: "Untreated vulnerabilities are the most common cause of successful cyber attacks.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "ISO 27001:2022 A.8", "BSI IT-Grundschutz OPS.1.1.6", "CIS Controls v8 7"] },
  { id: "p21-c01", title: "Automatisierte Schwachstellen-Scans", titleEn: "Automated Vulnerability Scans", description: "Automatisierte Schwachstellen-Scans müssen regelmäßig durchgeführt werden: mindestens wöchentlich für internetexponierte Systeme, mindestens monatlich für interne Systeme, und nach jeder wesentlichen Änderung. Scans müssen authentifizierte Scans umfassen. Scan-Ergebnisse müssen zentralisiert und mit Asset-Inventar korreliert werden.", descriptionEn: "Automated vulnerability scans must be conducted regularly: at least weekly for internet-exposed systems, at least monthly for internal systems, and after every significant change. Scans must include authenticated scans. Scan results must be centralised and correlated with asset inventory.", reason: "Regelmäßige Scans ermöglichen die kontinuierliche Identifikation neuer Schwachstellen.", reasonEn: "Regular scans enable continuous identification of new vulnerabilities.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz OPS.1.1.6", "CIS Controls v8 7.5", "NIST CSF 2.0 ID.RA-01"] },
  { id: "p21-c02", title: "Schwachstellen-Priorisierung", titleEn: "Vulnerability Prioritisation", description: "Identifizierte Schwachstellen müssen risikobasiert priorisiert werden — nicht nur nach CVSS-Score, sondern unter Berücksichtigung von: Asset-Kritikalität, Exposition, Verfügbarkeit von Exploits, aktive Ausnutzung (CISA KEV), Geschäftsauswirkung und kompensierende Kontrollen. SSVC oder vergleichbare Methoden sollten verwendet werden.", descriptionEn: "Identified vulnerabilities must be prioritised risk-based — not only by CVSS score but considering: asset criticality, exposure, exploit availability, active exploitation (CISA KEV), business impact, and compensating controls. SSVC or comparable methods should be used.", reason: "Kontextbasierte Priorisierung fokussiert Ressourcen auf die größten Risiken.", reasonEn: "Context-based prioritisation focuses resources on the greatest risks.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "CISA SSVC", "CIS Controls v8 7.4", "NIST CSF 2.0 ID.RA-01"] },
  { id: "p21-c03", title: "Behebungsfristen (SLA)", titleEn: "Remediation Timelines (SLA)", description: "Die Organisation muss verbindliche Behebungsfristen definieren: Kritisch (CVSS ≥9.0 oder aktiv ausgenutzt) — 48h; Hoch (7.0-8.9) — 14 Tage; Mittel (4.0-6.9) — 30 Tage; Niedrig (<4.0) — 90 Tage. Für internetexponierte Systeme müssen kürzere Fristen gelten.", descriptionEn: "The organisation must define binding remediation timelines: Critical (CVSS ≥9.0 or actively exploited) — 48h; High (7.0-8.9) — 14 days; Medium (4.0-6.9) — 30 days; Low (<4.0) — 90 days. Shorter timelines must apply for internet-exposed systems.", reason: "Ohne definierte Fristen bleibt die Behebung unverbindlich.", reasonEn: "Without defined timelines, remediation remains non-binding.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz OPS.1.1.6", "CIS Controls v8 7.4"] },
  { id: "p21-c04", title: "Verifizierung der Behebung", titleEn: "Remediation Verification", description: "Die erfolgreiche Behebung muss durch Re-Scans innerhalb von 72 Stunden nach der gemeldeten Behebung verifiziert werden. Schwachstellen dürfen erst nach erfolgreicher Verifizierung als behoben markiert werden.", descriptionEn: "Successful remediation must be verified through re-scans within 72 hours after reported remediation. Vulnerabilities may only be marked as remediated after successful verification.", reason: "Ohne Verifizierung besteht das Risiko unvollständiger Behebungen.", reasonEn: "Without verification, there is a risk of incomplete remediations.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "CIS Controls v8 7.7", "NIST CSF 2.0 RS.MI"] },
  { id: "p21-c05", title: "Operatives Anwendungs-Schwachstellenmanagement", titleEn: "Operational Application Vulnerability Management", description: "Produktive Webanwendungen und APIs müssen regelmäßig durch automatisierte DAST-Scans und manuelle Penetrationstests auf Schwachstellen getestet werden. OWASP Top 10 und API Security Top 10 müssen als Mindeststandard abgedeckt werden. Hinweis: SAST, Secure Coding Guidelines und CI/CD-Pipeline-Integration werden in p47–p49 (Secure Development) geregelt; diese Klausel adressiert ausschließlich die operative Prüfung produktiver Systeme.", descriptionEn: "Production web applications and APIs must be regularly tested through automated DAST scans and manual penetration tests. OWASP Top 10 and API Security Top 10 must be covered as minimum standard. Note: SAST, secure coding guidelines, and CI/CD pipeline integration are governed by p47–p49 (Secure Development); this clause addresses exclusively operational testing of production systems.", reason: "Anwendungs-Schwachstellen erfordern spezifische Testmethoden.", reasonEn: "Application vulnerabilities require specific testing methods.", whenRequired: "Erforderlich für alle Web-Anwendungen und APIs.", whenRequiredEn: "Required for all web applications and APIs.", sources: ["ISO 27001:2022 A.8.28", "OWASP", "CIS Controls v8 16.12", "BSI IT-Grundschutz APP.3.1"] },
  { id: "p21-c06", title: "Zero-Day-Schwachstellenmanagement", titleEn: "Zero-Day Vulnerability Management", description: "Die Organisation muss einen Prozess für den Umgang mit Zero-Day-Schwachstellen definieren: Monitoring von Bedrohungsintelligenz-Quellen, schnelle Bewertung der eigenen Betroffenheit, temporäre Mitigationsmaßnahmen, beschleunigte Patch-Bereitstellung und Kommunikation an Stakeholder.", descriptionEn: "The organisation must define a process for handling zero-day vulnerabilities: monitoring threat intelligence sources, rapid assessment of own exposure, temporary mitigation measures, accelerated patch deployment, and communication to stakeholders.", reason: "Zero-Day-Schwachstellen erfordern eine proaktive Reaktion.", reasonEn: "Zero-day vulnerabilities require a proactive response.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.7", "ISO 27001:2022 A.8", "NIST CSF 2.0 ID.RA-02"] },
  { id: "p21-c07", title: "Koordinierte Schwachstellen-Offenlegung", titleEn: "Coordinated Vulnerability Disclosure", description: "Die Organisation muss eine CVD/Responsible-Disclosure-Richtlinie veröffentlichen. Sicherheitsforscher müssen eine klare Kontaktmöglichkeit haben (security.txt, Bug-Bounty-Programm). ISO 27001:2022 A.5.7 Anforderungen müssen umgesetzt werden.", descriptionEn: "The organisation must publish a CVD/responsible disclosure policy. Security researchers must have a clear contact option (security.txt, bug bounty programme). ISO 27001:2022 A.5.7 requirements must be implemented.", reason: "CVD ermöglicht kontrollierte Behebung bevor öffentliche Ausnutzung.", reasonEn: "CVD enables controlled remediation before public exploitation.", whenRequired: "Erforderlich gemäß ISO 27001:2022 A.5.7.", whenRequiredEn: "Required per ISO 27001:2022 A.5.7.", sources: ["ISO 27001:2022 A.5.7", "ISO 29147:2018", "ISO 30111:2019", "BSI IT-Grundschutz"] },
  { id: "p21-c08", title: "Cloud-Schwachstellenmanagement", titleEn: "Cloud Vulnerability Management", description: "Cloud-Ressourcen müssen in das Schwachstellenmanagement einbezogen werden. CSPM Tools müssen Fehlkonfigurationen identifizieren. Shared-Responsibility-Modell muss dokumentiert werden. Container-Images müssen in Registries gescannt werden.", descriptionEn: "Cloud resources must be included in vulnerability management. CSPM tools must identify misconfigurations. Shared responsibility model must be documented. Container images must be scanned in registries.", reason: "Cloud-Umgebungen haben eigene Schwachstellenklassen.", reasonEn: "Cloud environments have their own vulnerability classes.", whenRequired: "Erforderlich bei Cloud-Nutzung.", whenRequiredEn: "Required when using cloud services.", sources: ["ISO 27001:2022 A.8.8", "BSI C5:2020", "CIS Cloud Benchmarks", "CIS Controls v8 7.5"] },
  { id: "p21-c09", title: "Schwachstellen-Metriken und operatives Reporting", titleEn: "Vulnerability Metrics and Operational Reporting", description: "Die Organisation muss operative Schwachstellen-Metriken definieren und monatlich berichten: Gesamtzahl offener Schwachstellen nach Schweregrad, Mean Time to Remediate (MTTR), Behebungsquote innerhalb SLA, Scan-Abdeckungsgrad, Anzahl überfälliger Schwachstellen. Diese Metriken dienen der operativen Steuerung und SLA-Einhaltung. Hinweis: Die strategische Trend-Analyse und systemische Ursachenforschung werden in p21-c22 geregelt.", descriptionEn: "The organisation must define operational vulnerability metrics and report monthly: total open vulnerabilities by severity, MTTR, remediation rate within SLA, scan coverage, overdue vulnerabilities. These metrics serve operational management and SLA compliance. Note: Strategic trend analysis and systemic root cause research are governed by p21-c22.", reason: "Ohne messbare KPIs kann der Erfolg nicht bewertet werden.", reasonEn: "Without measurable KPIs, success cannot be evaluated.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §9.1", "NIST CSF 2.0 ID.IM", "CIS Controls v8 7"] },
  { id: "p21-c10", title: "Kompensierende Kontrollen", titleEn: "Compensating Controls", description: "Wenn Schwachstellen nicht innerhalb der SLA behoben werden können, müssen kompensierende Kontrollen implementiert, dokumentiert, regelmäßig überprüft und nach Behebung entfernt werden.", descriptionEn: "When vulnerabilities cannot be remediated within SLA, compensating controls must be implemented, documented, regularly reviewed, and removed once remediated.", reason: "Kompensierende Kontrollen reduzieren das Risiko in der Zwischenzeit.", reasonEn: "Compensating controls reduce risk in the interim.", whenRequired: "Bei nicht fristgerecht behebbaren Schwachstellen.", whenRequiredEn: "When vulnerabilities cannot be remediated within deadlines.", sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz", "PCI DSS v4"] },
  { id: "p21-c11", title: "Schwachstellendatenbank und Tracking", titleEn: "Vulnerability Database and Tracking", description: "Alle identifizierten Schwachstellen müssen in einer zentralen Datenbank über ihren gesamten Lebenszyklus verfolgt werden mit: Schwachstelle, betroffene Assets, CVSS-Score, Priorität, Verantwortlicher, Status, Fristen und Behebungsdatum.", descriptionEn: "All identified vulnerabilities must be tracked in a central database throughout their lifecycle with: vulnerability, affected assets, CVSS score, priority, responsible person, status, deadlines, and remediation date.", reason: "Ohne zentrale Verfolgung gehen Schwachstellen verloren.", reasonEn: "Without central tracking, vulnerabilities are lost.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "CIS Controls v8 7.1"] },
  { id: "p21-c12", title: "OT/ICS-Schwachstellenmanagement", titleEn: "OT/ICS Vulnerability Management", description: "OT/ICS-Systeme müssen in das Schwachstellenmanagement einbezogen werden mit OT-spezifischen Anforderungen: passive Scanning-Methoden, Herstellerabsprachen, längere Testzyklen, kompensierende Kontrollen bei nicht patchbaren Systemen.", descriptionEn: "OT/ICS systems must be included in vulnerability management with OT-specific requirements: passive scanning, vendor coordination, longer testing cycles, compensating controls for non-patchable systems.", reason: "OT/ICS-Systeme erfordern angepasstes Schwachstellenmanagement.", reasonEn: "OT/ICS systems require adapted vulnerability management.", whenRequired: "Erforderlich bei OT/ICS-Betrieb.", whenRequiredEn: "Required when operating OT/ICS.", sources: ["IEC 62443", "ISO 27001:2022 A.8", "BSI IT-Grundschutz IND.1"] },
  { id: "p21-c13", title: "Penetrationstests", titleEn: "Penetration Testing", description: "Die Organisation muss mindestens jährlich Penetrationstests durch qualifizierte, unabhängige Tester durchführen lassen. Tests müssen externe und interne Perspektiven abdecken. Ergebnisse müssen priorisiert behandelt und durch Re-Tests verifiziert werden.", descriptionEn: "The organisation must conduct penetration tests at least annually by qualified, independent testers. Tests must cover external and internal perspectives. Results must be treated with priority and verified through re-tests.", reason: "Penetrationstests identifizieren Schwachstellen, die Scanner nicht erkennen.", reasonEn: "Penetration tests identify vulnerabilities that scanners cannot detect.", whenRequired: "Mindestens jährlich.", whenRequiredEn: "At least annually.", sources: ["ISO 27001:2022 A.8.8", "ISO 27001:2022 A.8", "BSI IT-Grundschutz DER.3.3", "CIS Controls v8 18"] },
  { id: "p21-c14", title: "Schwachstellen-Monitoring für Open-Source-Abhängigkeiten", titleEn: "Vulnerability Monitoring for Open-Source Dependencies", description: "Open-Source-Abhängigkeiten in produktiven Systemen müssen kontinuierlich auf bekannte Schwachstellen überwacht werden (Dependabot, Snyk, OWASP Dependency-Check). Verwundbare Bibliotheken müssen gemäß SLAs aktualisiert werden. Hinweis: SBOM-Erstellung und CI/CD-Integration werden in p47 (Secure Development) geregelt; diese Klausel adressiert ausschließlich das operative Monitoring produktiver Deployments.", descriptionEn: "Open-source dependencies in production systems must be continuously monitored for known vulnerabilities (Dependabot, Snyk, OWASP Dependency-Check). Vulnerable libraries must be updated per SLAs. Note: SBOM creation and CI/CD integration are governed by p47 (Secure Development); this clause addresses exclusively operational monitoring of production deployments.", reason: "Open-Source-Schwachstellen können massive Auswirkungen haben.", reasonEn: "Open-source vulnerabilities can have massive impact.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.19-23", "ISO 27001:2022 A.8.28", "CIS Controls v8 16.4", "NIST CSF 2.0 GV.SC"] },
  { id: "p21-c15", title: "Schwachstellen-Eskalation", titleEn: "Vulnerability Escalation", description: "Die Organisation muss Eskalationsprozesse definieren. Kritische Schwachstellen mit aktiver Ausnutzung müssen sofort eskaliert werden. Überfällige Schwachstellen müssen stufenweise eskaliert werden: Asset-Owner → IT-Leitung → CISO → Geschäftsführung.", descriptionEn: "The organisation must define escalation processes. Critical vulnerabilities with active exploitation must be immediately escalated. Overdue vulnerabilities must be escalated in stages: asset owner → IT management → CISO → executive management.", reason: "Ohne Eskalation bleiben kritische Schwachstellen unbehandelt.", reasonEn: "Without escalation, critical vulnerabilities remain untreated.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz OPS.1.1.6"] },
  { id: "p21-c16", title: "Externe Schwachstellen-Informationsquellen", titleEn: "External Vulnerability Information Sources", description: "Die Organisation muss relevante externe Quellen aktiv überwachen: NVD/CVE, BSI CERT-Bund, CISA KEV, herstellerspezifische Advisories, branchenspezifische CERTs und ISACs.", descriptionEn: "The organisation must actively monitor relevant external sources: NVD/CVE, BSI CERT-Bund, CISA KEV, vendor-specific advisories, sector-specific CERTs and ISACs.", reason: "Proaktive Überwachung verkürzt die Erkennungszeit.", reasonEn: "Proactive monitoring shortens detection time.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.7", "ISO 27001:2022 A.5.6", "BSI IT-Grundschutz OPS.1.1.6"] },
  { id: "p21-c17", title: "Schwachstellen-Ausschlüsse und Risikoakzeptanz", titleEn: "Vulnerability Exclusions and Risk Acceptance", description: "Bewusst nicht behobene Schwachstellen müssen formal als Risiko akzeptiert werden mit: Begründung, bewertetem Restrisiko, kompensierenden Kontrollen, Verantwortlichem und Überprüfungsdatum. Risikoakzeptanzen müssen mindestens jährlich überprüft werden.", descriptionEn: "Intentionally not remediated vulnerabilities must be formally accepted as risk with: justification, assessed residual risk, compensating controls, responsible person, and review date. Risk acceptances must be reviewed at least annually.", reason: "Undokumentierte Risikoakzeptanz führt zu unkontrollierten Risiken.", reasonEn: "Undocumented risk acceptance leads to uncontrolled risks.", whenRequired: "Bei bewusster Nichtbehebung.", whenRequiredEn: "When intentionally not remediating.", sources: ["ISO 27001:2022 §6.1.3", "BSI-Standard 200-3"] },
  { id: "p21-c18", title: "Attack Surface Management", titleEn: "Attack Surface Management", description: "Die Organisation muss ihre externe Angriffsfläche kontinuierlich überwachen. EASM Tools müssen unbekannte, internetexponierte Assets, offene Ports, abgelaufene Zertifikate und Shadow-IT identifizieren. Ergebnisse müssen in den Schwachstellenmanagement-Prozess einfließen.", descriptionEn: "The organisation must continuously monitor its external attack surface. EASM tools must identify unknown, internet-exposed assets, open ports, expired certificates, and shadow IT. Results must feed into the vulnerability management process.", reason: "EASM identifiziert unbekannte Expositionen.", reasonEn: "EASM identifies unknown exposures.", whenRequired: "Empfohlen für alle, erforderlich für Organisationen mit großer Internetpräsenz.", whenRequiredEn: "Recommended for all, required for organisations with large internet presence.", sources: ["ISO 27001:2022 A.8.8", "CIS Controls v8 7.5", "NIST CSF 2.0 ID.AM"] },
  { id: "p21-c19", title: "Schwachstellen-Scan-Scope und -Abdeckung", titleEn: "Vulnerability Scan Scope and Coverage", description: "Der Scan-Scope muss 100% aller IT-Assets abdecken. Die Scan-Abdeckung muss als KPI überwacht werden. Nicht scannbare Assets müssen dokumentiert und alternative Bewertungsmethoden definiert werden.", descriptionEn: "The scan scope must cover 100% of all IT assets. Scan coverage must be monitored as a KPI. Non-scannable assets must be documented and alternative assessment methods defined.", reason: "Ungescannte Assets sind blinde Flecken.", reasonEn: "Unscanned assets are blind spots.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "CIS Controls v8 7.5"] },
  { id: "p21-c20", title: "Container-Image-Schwachstellenmanagement", titleEn: "Container Image Vulnerability Management", description: "Container-Images müssen in der Registry auf Schwachstellen gescannt werden. Admission-Controller müssen das Deployment verwundbarer Images verhindern. Base-Images müssen regelmäßig aktualisiert werden.", descriptionEn: "Container images must be scanned for vulnerabilities in the registry. Admission controllers must prevent deployment of vulnerable images. Base images must be regularly updated.", reason: "Verwundbare Container-Images multiplizieren die Angriffsfläche.", reasonEn: "Vulnerable container images multiply the attack surface.", whenRequired: "Erforderlich bei Container-Nutzung.", whenRequiredEn: "Required when using containers.", sources: ["NIST SP 800-190", "CIS Kubernetes Benchmark", "CIS Controls v8 7.5"] },
  { id: "p21-c21", title: "Bug-Bounty-Programm", titleEn: "Bug Bounty Programme", description: "Die Organisation sollte ein Bug-Bounty-Programm einrichten. Scope, Belohnungsstruktur, Safe-Harbor-Regeln und Kommunikationsprozesse müssen definiert werden.", descriptionEn: "The organisation should establish a bug bounty programme. Scope, reward structure, safe harbour rules, and communication processes must be defined.", reason: "Bug-Bounty-Programme erweitern die Schwachstellenerkennung kosteneffektiv.", reasonEn: "Bug bounty programmes extend vulnerability detection cost-effectively.", whenRequired: "Empfohlen.", whenRequiredEn: "Recommended.", sources: ["ISO 27001:2022 A.5.7", "ISO 29147:2018"] },
  { id: "p21-c22", title: "Strategische Schwachstellen-Trend-Analyse", titleEn: "Strategic Vulnerability Trend Analysis", description: "Die Organisation muss vierteljährlich strategische Trend-Analysen durchführen, um systemische Probleme und Architektur-Schwächen zu identifizieren — z.B. wiederkehrende Schwachstellenklassen, Systeme mit überdurchschnittlich vielen Schwachstellen. Ergebnisse müssen in Architektur- und Beschaffungsverbesserungen einfließen. Hinweis: Die operative monatliche Metrikerhebung (MTTR, SLA-Compliance) wird in p21-c09 geregelt.", descriptionEn: "The organisation must conduct quarterly strategic trend analyses to identify systemic issues and architectural weaknesses — e.g., recurring vulnerability classes, systems with above-average vulnerabilities. Results must inform architecture and procurement improvements. Note: Operational monthly metric collection (MTTR, SLA compliance) is governed by p21-c09.", reason: "Trend-Analysen ermöglichen die Behebung von Ursachen statt Symptomen.", reasonEn: "Trend analyses enable remediation of root causes rather than symptoms.", whenRequired: "Mindestens vierteljährlich.", whenRequiredEn: "At least quarterly.", sources: ["ISO 27001:2022 §10.1", "NIST CSF 2.0 ID.IM"] },
  { id: "p21-c23", title: "Schwachstellen-Integration in Risikomanagement", titleEn: "Vulnerability Integration in Risk Management", description: "Schwachstellendaten müssen in das übergreifende Risikomanagement integriert werden. Kritische Schwachstellen müssen als Risikoindikatoren behandelt und im Risikoregister reflektiert werden.", descriptionEn: "Vulnerability data must be integrated into overarching risk management. Critical vulnerabilities must be treated as risk indicators and reflected in the risk register.", reason: "Schwachstellen sind ein direkter Risikotreiber.", reasonEn: "Vulnerabilities are a direct risk driver.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §6.1.2", "BSI-Standard 200-3", "NIST CSF 2.0 ID.RA"] },
  { id: "p21-c24", title: "Zafiyet-spezifische automatisierte Remediation", titleEn: "Vulnerability-Specific Automated Remediation", description: "Die Organisation sollte automatisierte Remediation spezifisch für CVE-bezogene Schwachstellenbehebung implementieren — z.B. automatisches OS-/Anwendungspatching, automatische Container-Image-Updates bei bekannten CVEs. Automatisierte Remediation muss in Testumgebungen validiert werden. Hinweis: Automatisierte Konfigurationskorrektur (Härtungsdrift-Remediation) wird in p18-c21 geregelt.", descriptionEn: "The organisation should implement automated remediation specifically for CVE-related vulnerability fixing — e.g., automatic OS/application patching, automatic container image updates for known CVEs. Automated remediation must be validated in test environments. Note: Automated configuration correction (hardening drift remediation) is governed by p18-c21.", reason: "Automatisierte Remediation reduziert die MTTR drastisch.", reasonEn: "Automated remediation drastically reduces MTTR.", whenRequired: "Empfohlen.", whenRequiredEn: "Recommended.", sources: ["CIS Controls v8 7.4", "NIST CSF 2.0 RS.MI"] },
];

// ═══════════════════════════════════════════════════════════════
// P22 — Patch Management Policy (22 clauses)
// ═══════════════════════════════════════════════════════════════
const p22: PolicyClause[] = [
  { id: "p22-c00", title: "Patch-Management-Prozess", titleEn: "Patch Management Process", description: "Die Organisation muss einen formalisierten Patch-Management-Prozess betreiben, der alle Phasen abdeckt: Identifikation verfügbarer Patches, Bewertung und Priorisierung, Test, Genehmigung, Verteilung, Verifizierung und Berichterstattung. Der Prozess muss alle IT-Assets abdecken — Betriebssysteme, Anwendungen, Firmware, Netzwerkgeräte, Cloud-Ressourcen.", descriptionEn: "The organisation must operate a formalised patch management process covering all phases: identification of available patches, assessment and prioritisation, testing, approval, distribution, verification, and reporting. The process must cover all IT assets — operating systems, applications, firmware, network devices, cloud resources.", reason: "Ein strukturierter Patch-Management-Prozess stellt sicher, dass Sicherheitsupdates zeitnah und kontrolliert eingespielt werden.", reasonEn: "A structured patch management process ensures security updates are applied promptly and in a controlled manner.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "ISO 27001:2022 A.8", "BSI IT-Grundschutz OPS.1.1.3", "CIS Controls v8 7"] },
  { id: "p22-c01", title: "Patch-Priorisierung und SLAs", titleEn: "Patch Prioritisation and SLAs", description: "Patches müssen risikobasiert priorisiert werden. Verbindliche SLAs für die Patch-Installation müssen definiert werden: Kritische Sicherheitspatches — 48 Stunden (Notfallpatches: 24 Stunden); Hohe Sicherheitspatches — 7 Tage; Mittlere Patches — 30 Tage; Niedrige Patches — nächstes Wartungsfenster. Internetexponierte Systeme müssen kürzere SLAs haben.", descriptionEn: "Patches must be prioritised risk-based. Binding SLAs for patch installation must be defined: Critical security patches — 48 hours (emergency patches: 24 hours); High security patches — 7 days; Medium patches — 30 days; Low patches — next maintenance window. Internet-exposed systems must have shorter SLAs.", reason: "Ohne definierte SLAs bleibt Patching unverbindlich und kritische Systeme bleiben zu lange verwundbar.", reasonEn: "Without defined SLAs, patching remains non-binding and critical systems remain vulnerable too long.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz OPS.1.1.3", "CIS Controls v8 7.4"] },
  { id: "p22-c02", title: "Patch-Test und Validierung", titleEn: "Patch Testing and Validation", description: "Patches müssen vor dem produktiven Rollout in einer repräsentativen Testumgebung getestet werden. Tests müssen Funktionalität, Kompatibilität und Sicherheit überprüfen. Notfallpatches können mit verkürztem Testverfahren eingespielt werden, müssen aber nachträglich vollständig getestet werden. Automatisierte Regressionstests sollten implementiert werden.", descriptionEn: "Patches must be tested in a representative test environment before production rollout. Tests must verify functionality, compatibility, and security. Emergency patches may be applied with abbreviated testing procedures but must be fully tested retrospectively. Automated regression tests should be implemented.", reason: "Ungetestete Patches können Systemausfälle, Kompatibilitätsprobleme und neue Schwachstellen verursachen.", reasonEn: "Untested patches can cause system failures, compatibility issues, and new vulnerabilities.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3"] },
  { id: "p22-c03", title: "Automatisierte Patch-Verteilung", titleEn: "Automated Patch Distribution", description: "Patches müssen über automatisierte Verteilungssysteme (WSUS, SCCM, Intune, Ansible, Satellite, etc.) ausgerollt werden. Manuelle Patch-Installation muss auf Ausnahmefälle beschränkt sein. Der Verteilungsstatus muss in Echtzeit überwacht werden. Fehlgeschlagene Patch-Installationen müssen automatisch eskaliert werden.", descriptionEn: "Patches must be rolled out via automated distribution systems (WSUS, SCCM, Intune, Ansible, Satellite, etc.). Manual patch installation must be limited to exceptional cases. Distribution status must be monitored in real-time. Failed patch installations must be automatically escalated.", reason: "Manuelle Patch-Verteilung ist langsam, fehleranfällig und nicht skalierbar.", reasonEn: "Manual patch distribution is slow, error-prone, and not scalable.", whenRequired: "Immer erforderlich ab mittlerer Umgebungsgröße.", whenRequiredEn: "Always required from medium environment size.", sources: ["CIS Controls v8 7.3", "BSI IT-Grundschutz OPS.1.1.3"] },
  { id: "p22-c04", title: "Notfall-Patch-Verfahren", titleEn: "Emergency Patch Procedure", description: "Für kritische Sicherheitspatches, die eine sofortige Anwendung erfordern (aktiv ausgenutzte Schwachstellen), muss ein beschleunigtes Verfahren definiert sein. Das Verfahren muss verkürzte Genehmigungswege, reduzierte Testanforderungen und sofortige Verteilung ermöglichen. Alle Notfallpatches müssen nachträglich vollständig dokumentiert und getestet werden.", descriptionEn: "For critical security patches requiring immediate application (actively exploited vulnerabilities), an expedited procedure must be defined. The procedure must enable shortened approval paths, reduced testing requirements, and immediate distribution. All emergency patches must be retrospectively fully documented and tested.", reason: "Bei aktiv ausgenutzten Schwachstellen kann der normale Patch-Prozess zu langsam sein und das Risiko unakzeptabel erhöhen.", reasonEn: "For actively exploited vulnerabilities, the normal patch process may be too slow and increase risk unacceptably.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz OPS.1.1.3", "CISA KEV"] },
  { id: "p22-c05", title: "Rollback-Planung", titleEn: "Rollback Planning", description: "Vor jeder Patch-Installation muss ein Rollback-Plan definiert werden. Backups oder Snapshots müssen vor dem Patching erstellt werden. Die Rollback-Prozedur muss getestet und dokumentiert sein. Im Falle eines fehlerhaften Patches muss der Rollback innerhalb der definierten RTO durchführbar sein.", descriptionEn: "Before each patch installation, a rollback plan must be defined. Backups or snapshots must be created before patching. The rollback procedure must be tested and documented. In case of a faulty patch, rollback must be feasible within the defined RTO.", reason: "Ohne Rollback-Fähigkeit können fehlerhafte Patches zu längeren Ausfällen führen.", reasonEn: "Without rollback capability, faulty patches can lead to extended outages.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3"] },
  { id: "p22-c06", title: "Operatives Patch-Compliance-Monitoring", titleEn: "Operational Patch Compliance Monitoring", description: "Der Patch-Status aller Systeme muss kontinuierlich und automatisiert überwacht werden. Ein Echtzeit-Compliance-Dashboard muss den aktuellen Patch-Level nach Systemklasse, Kritikalität und Geschäftsbereich darstellen. Systeme mit fehlenden kritischen Patches müssen automatisch als nicht-konform markiert und der zuständige Asset-Owner benachrichtigt werden. Diese Klausel regelt die operative Echtzeitüberwachung; die strategische Berichterstattung und KPI-Auswertung auf Management-Ebene wird in p22-c14 geregelt.", descriptionEn: "The patch status of all systems must be continuously and automatically monitored. A real-time compliance dashboard must display the current patch level by system class, criticality, and business unit. Systems missing critical patches must be automatically flagged as non-compliant and the responsible asset owner notified. This clause governs operational real-time monitoring; strategic management-level reporting and KPI evaluation is governed in p22-c14.", reason: "Ohne kontinuierliche operative Überwachung bleibt der tatsächliche Patch-Status unbekannt und Lücken werden übersehen.", reasonEn: "Without continuous operational monitoring, the actual patch status remains unknown and gaps are overlooked.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "CIS Controls v8 7.4", "NIST CSF 2.0 DE.CM-09"] },
  { id: "p22-c07", title: "Firmware-Patching", titleEn: "Firmware Patching", description: "Firmware-Updates für Netzwerkgeräte, Server (BIOS/UEFI, BMC/IPMI), Storage-Systeme und IoT-Geräte müssen in den Patch-Management-Prozess einbezogen werden. Firmware-Updates müssen priorisiert werden, wenn Sicherheitslücken identifiziert werden. Die Firmware-Version aller Geräte muss im Asset-Inventar dokumentiert sein.", descriptionEn: "Firmware updates for network devices, servers (BIOS/UEFI, BMC/IPMI), storage systems, and IoT devices must be included in the patch management process. Firmware updates must be prioritised when security vulnerabilities are identified. The firmware version of all devices must be documented in the asset inventory.", reason: "Firmware-Schwachstellen werden oft übersehen, können aber tiefgreifende Kompromittierungen ermöglichen.", reasonEn: "Firmware vulnerabilities are often overlooked but can enable deep compromises.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz SYS.1.1", "CIS Controls v8 7.3"] },
  { id: "p22-c08", title: "Third-Party-Anwendungs-Patching", titleEn: "Third-Party Application Patching", description: "Drittanbieter-Anwendungen (Browser, PDF-Reader, Java, Office-Suiten, etc.) müssen ebenso konsequent gepatcht werden wie Betriebssysteme. Automatisierte Patch-Management-Tools müssen Drittanbieter-Software abdecken. Nicht mehr unterstützte Drittanbieter-Software muss identifiziert und ersetzt werden.", descriptionEn: "Third-party applications (browsers, PDF readers, Java, office suites, etc.) must be patched as consistently as operating systems. Automated patch management tools must cover third-party software. No longer supported third-party software must be identified and replaced.", reason: "Drittanbieter-Anwendungen sind ein häufig übersehener Angriffsvektor mit kritischen Schwachstellen.", reasonEn: "Third-party applications are a frequently overlooked attack vector with critical vulnerabilities.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "CIS Controls v8 7.4", "BSI IT-Grundschutz OPS.1.1.3"] },
  { id: "p22-c09", title: "Wartungsfenster und Patch-Planung", titleEn: "Maintenance Windows and Patch Scheduling", description: "Regelmäßige Wartungsfenster müssen für das Einspielen von Patches definiert werden. Die Planung muss Geschäftsanforderungen und Verfügbarkeitsanforderungen berücksichtigen. Für kritische 24/7-Systeme müssen Rolling-Update-Verfahren oder Redundanz-basierte Patching-Strategien implementiert werden. Patch-Zeitpläne müssen mit betroffenen Stakeholdern abgestimmt werden.", descriptionEn: "Regular maintenance windows must be defined for applying patches. Planning must consider business requirements and availability requirements. For critical 24/7 systems, rolling update procedures or redundancy-based patching strategies must be implemented. Patch schedules must be coordinated with affected stakeholders.", reason: "Unkooordiniertes Patching kann zu unerwarteten Ausfällen und Geschäftsunterbrechungen führen.", reasonEn: "Uncoordinated patching can lead to unexpected outages and business interruptions.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3", "ITIL Change Management"] },
  { id: "p22-c10", title: "End-of-Life-Software-Management (Patch-Perspektive)", titleEn: "End-of-Life Software Management (Patch Perspective)", description: "Software, die das End-of-Life (EOL) erreicht hat und keine Sicherheitsupdates mehr erhält, muss aus Patch-Perspektive identifiziert werden: Migration auf unterstützte Versionen muss eingeplant, Übergangszeiträume mit kompensierenden Kontrollen (Netzwerkisolierung, Enhanced Monitoring, Application Whitelisting, Virtual Patching gemäß p22-c19) abgesichert und EOL-Software im Risikoregister erfasst werden. Die Erstidentifikation und risikobasierte Bewertung von EOL-Software erfolgt im Rahmen des Vulnerability-Management-Prozesses (p21); diese Klausel regelt die patch-spezifischen Migrationsmaßnahmen und kompensierenden Kontrollen.", descriptionEn: "Software that has reached End-of-Life (EOL) and no longer receives security updates must be identified from a patch perspective: migration to supported versions must be planned, transition periods secured with compensating controls (network isolation, enhanced monitoring, application whitelisting, virtual patching per p22-c19), and EOL software recorded in the risk register. Initial identification and risk-based assessment of EOL software is handled within the vulnerability management process (p21); this clause governs patch-specific migration measures and compensating controls.", reason: "EOL-Software erhält keine Sicherheitspatches und stellt ein dauerhaftes, wachsendes Sicherheitsrisiko dar.", reasonEn: "EOL software receives no security patches and represents a permanent, growing security risk.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz OPS.1.1.3", "CIS Controls v8 2.2"] },
  { id: "p22-c11", title: "Patch-Impact-Assessment", titleEn: "Patch Impact Assessment", description: "Vor der Installation von Patches muss eine Impact-Bewertung durchgeführt werden, die mögliche Auswirkungen auf Systemfunktionalität, Anwendungskompatibilität, Performance und Abhängigkeiten identifiziert. Die Bewertung muss den Schweregrad des Patches gegen das Risiko eines Ausfalls durch den Patch abwägen.", descriptionEn: "Before patch installation, an impact assessment must be conducted identifying potential effects on system functionality, application compatibility, performance, and dependencies. The assessment must weigh the severity of the patch against the risk of outage from the patch.", reason: "Patches können unerwünschte Nebenwirkungen haben, die ohne vorherige Bewertung zu Ausfällen führen.", reasonEn: "Patches can have unwanted side effects that lead to outages without prior assessment.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.32", "BSI IT-Grundschutz OPS.1.1.3"] },
  { id: "p22-c12", title: "Cloud-Service-Patching", titleEn: "Cloud Service Patching", description: "Für Cloud-Dienste muss das Shared-Responsibility-Modell bezüglich Patching dokumentiert sein. IaaS: Organisation ist für OS- und Anwendungspatching verantwortlich; PaaS: Organisation für Anwendungspatching; SaaS: Provider für alles. Cloud-native Patching-Mechanismen (automatische OS-Updates, Container-Rebuild) müssen genutzt werden.", descriptionEn: "For cloud services, the shared responsibility model regarding patching must be documented. IaaS: organisation responsible for OS and application patching; PaaS: organisation for application patching; SaaS: provider for everything. Cloud-native patching mechanisms (automatic OS updates, container rebuild) must be utilised.", reason: "Unklarheiten im Shared-Responsibility-Modell führen zu Patching-Lücken.", reasonEn: "Unclear shared responsibility models lead to patching gaps.", whenRequired: "Erforderlich bei Cloud-Nutzung.", whenRequiredEn: "Required when using cloud services.", sources: ["BSI C5:2020", "ISO 27001:2022 A.8.8", "CIS Controls v8 7.3"] },
  { id: "p22-c13", title: "OT/ICS-Patching", titleEn: "OT/ICS Patching", description: "OT/ICS-Systeme müssen in den Patch-Management-Prozess einbezogen werden, wobei OT-spezifische Anforderungen berücksichtigt werden: Herstellerfreigabe vor dem Patching, erweiterte Testphasen, geplante Stillstände für die Patch-Installation, Fallback-Prozeduren. Virtual Patching muss als Alternative für nicht patchbare Systeme evaluiert werden.", descriptionEn: "OT/ICS systems must be included in the patch management process with OT-specific requirements considered: vendor approval before patching, extended testing phases, planned shutdowns for patch installation, fallback procedures. Virtual patching must be evaluated as alternative for non-patchable systems.", reason: "OT/ICS-Systeme haben besondere Anforderungen (Verfügbarkeit, Zertifizierungen), die ein angepasstes Patching erfordern.", reasonEn: "OT/ICS systems have special requirements (availability, certifications) that require adapted patching.", whenRequired: "Erforderlich bei OT/ICS-Betrieb.", whenRequiredEn: "Required when operating OT/ICS.", sources: ["IEC 62443", "BSI IT-Grundschutz IND.1", "ISO 27001:2022 A.8"] },
  { id: "p22-c14", title: "Strategische Patch-Berichterstattung und KPIs", titleEn: "Strategic Patch Reporting and KPIs", description: "Die Organisation muss auf Management-Ebene monatlich strategische Patch-KPIs berichten: Mean Time to Patch (MTTP) pro Schweregrad, Trend der Patch-Compliance-Rate, Anzahl überfälliger Patches nach Schweregrad und Geschäftsbereich, EOL-Software-Bestand und Migrationsfortschritt (vgl. p22-c10), Benchmark-Vergleiche mit Vorperioden. Diese strategische Berichterstattung ergänzt das operative Echtzeit-Monitoring in p22-c06, das sich auf die tagesaktuelle Dashboard-Überwachung und automatische Noncompliance-Markierung konzentriert.", descriptionEn: "The organisation must report strategic patch KPIs monthly at management level: Mean Time to Patch (MTTP) per severity, patch compliance rate trends, number of overdue patches by severity and business unit, EOL software inventory and migration progress (cf. p22-c10), benchmark comparisons with prior periods. This strategic reporting complements the operational real-time monitoring in p22-c06, which focuses on daily dashboard monitoring and automatic noncompliance flagging.", reason: "Ohne strategische KPIs ist der Patch-Management-Prozess auf Management-Ebene nicht steuerbar.", reasonEn: "Without strategic KPIs, the patch management process cannot be governed at management level.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 §9.1", "NIST CSF 2.0 ID.IM"] },
  { id: "p22-c15", title: "Patch-Verifizierung und Nachkontrolle", titleEn: "Patch Verification and Post-Check", description: "Nach dem Einspielen von Patches muss verifiziert werden, dass der Patch erfolgreich installiert wurde und die Schwachstelle tatsächlich geschlossen ist. Systemfunktionalität muss nach dem Patching geprüft werden. Vulnerability-Re-Scans müssen die Behebung bestätigen. Fehlgeschlagene Patch-Installationen müssen nachverfolgt werden.", descriptionEn: "After applying patches, it must be verified that the patch was successfully installed and the vulnerability is actually closed. System functionality must be checked after patching. Vulnerability re-scans must confirm remediation. Failed patch installations must be tracked.", reason: "Patches können fehlschlagen oder unvollständig installiert werden, ohne dass dies sofort bemerkt wird.", reasonEn: "Patches can fail or be incompletely installed without this being immediately noticed.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "CIS Controls v8 7.7"] },
  { id: "p22-c16", title: "Patch-Verteilung für Remote-Arbeitsplätze", titleEn: "Patch Distribution for Remote Workstations", description: "Stationäre und mobile Geräte, die sich häufig außerhalb des Unternehmensnetzwerks befinden (Homeoffice-Laptops, Remote-Arbeitsplätze), müssen über internetbasierte Patch-Management-Mechanismen (Cloud-basiertes Patching, Always-On-VPN, NAC-Integration) versorgt werden. Der Patch-Status muss beim Netzwerkzugang geprüft und nicht gepatchte Geräte in Quarantäne gestellt werden. Die gerätespezifische MDM-Konfiguration mobiler Endgeräte (Smartphones, Tablets) — einschließlich OS-Mindestversionen und Compliance-Enforcement — wird in p23 (MDM-Richtlinie, insbesondere p23-c07) geregelt.", descriptionEn: "Stationary and mobile devices frequently outside the corporate network (home office laptops, remote workstations) must be served via internet-based patch management mechanisms (cloud-based patching, always-on VPN, NAC integration). Patch status must be checked during network access and unpatched devices quarantined. Device-specific MDM configuration of mobile endpoints (smartphones, tablets) — including OS minimum versions and compliance enforcement — is governed in p23 (MDM Policy, specifically p23-c07).", reason: "Remote-Geräte verpassen oft Patch-Zyklen und werden zu Schwachstellen im Sicherheitsperimeter.", reasonEn: "Remote devices often miss patch cycles and become vulnerabilities in the security perimeter.", whenRequired: "Erforderlich bei Remote-Arbeit.", whenRequiredEn: "Required for remote work.", sources: ["ISO 27001:2022 A.6.7", "CIS Controls v8 7.3", "BSI IT-Grundschutz INF.9"] },
  { id: "p22-c17", title: "Patch-Management-Eskalation", titleEn: "Patch Management Escalation", description: "Überfällige Patches müssen nach definierten Stufen eskaliert werden: nach SLA-Überschreitung → Asset-Owner; nach doppelter SLA-Überschreitung → IT-Leitung; nach dreifacher SLA-Überschreitung → CISO. Bei kritischen überfälligen Patches muss die Geschäftsführung informiert werden.", descriptionEn: "Overdue patches must be escalated in defined stages: after SLA breach → asset owner; after double SLA breach → IT management; after triple SLA breach → CISO. For critical overdue patches, executive management must be informed.", reason: "Ohne Eskalation bleiben überfällige Patches unbeachtet und das Risiko steigt.", reasonEn: "Without escalation, overdue patches remain unattended and risk increases.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz OPS.1.1.3"] },
  { id: "p22-c18", title: "Patch-Automatisierung und Self-Healing", titleEn: "Patch Automation and Self-Healing", description: "Die Organisation sollte automatisiertes Patching (Sicherheitsupdates, OS-Patches, Container-Image-Rebuild) für Standardsysteme implementieren, wo dies sicher möglich ist. Self-Healing-Mechanismen (automatischer Neustart nach Update, automatische Container-Neuerstellung) sollten für unkritische Systeme eingesetzt werden. Automatisierungsentscheidungen müssen risikobewert und dokumentiert sein. Diese Klausel regelt die automatisierte Anwendung von Sicherheitspatches; die automatisierte Korrektur von Konfigurationsabweichungen (Härtungsdrift-Remediation) wird in p18-c21 geregelt.", descriptionEn: "The organisation should implement automated patching (security updates, OS patches, container image rebuild) for standard systems where safely possible. Self-healing mechanisms (automatic restart after update, automatic container rebuild) should be deployed for non-critical systems. Automation decisions must be risk-assessed and documented. This clause governs automated application of security patches; automated correction of configuration deviations (hardening drift remediation) is governed in p18-c21.", reason: "Automatisierung reduziert die Mean Time to Patch und den manuellen Aufwand erheblich.", reasonEn: "Automation significantly reduces Mean Time to Patch and manual effort.", whenRequired: "Empfohlen.", whenRequiredEn: "Recommended.", sources: ["CIS Controls v8 7.4", "NIST CSF 2.0 PR.PS"] },
  { id: "p22-c19", title: "Virtual Patching", titleEn: "Virtual Patching", description: "Wenn reguläres Patching nicht möglich oder nicht rechtzeitig durchführbar ist, muss Virtual Patching (IPS-Regeln, WAF-Regeln) als temporäre Maßnahme implementiert werden. Virtual Patches müssen als kompensierende Kontrolle dokumentiert und entfernt werden, sobald der reguläre Patch eingespielt ist. Virtual Patching ist kein dauerhafter Ersatz für reguläres Patching.", descriptionEn: "When regular patching is not possible or not feasible in time, virtual patching (IPS rules, WAF rules) must be implemented as a temporary measure. Virtual patches must be documented as compensating controls and removed once the regular patch is applied. Virtual patching is not a permanent substitute for regular patching.", reason: "Virtual Patching schließt die Schutzlücke zwischen Schwachstellenerkennung und regulärem Patch.", reasonEn: "Virtual patching closes the protection gap between vulnerability detection and regular patching.", whenRequired: "Erforderlich als Zwischenlösung.", whenRequiredEn: "Required as interim solution.", sources: ["ISO 27001:2022 A.8.8", "BSI IT-Grundschutz OPS.1.1.3"] },
  { id: "p22-c20", title: "Patch-Inventar und Statusdokumentation", titleEn: "Patch Inventory and Status Documentation", description: "Die Organisation muss ein zentrales Patch-Inventar führen, das für jedes System den aktuellen Patch-Level, installierte Patches, ausstehende Patches und die Patch-Historie dokumentiert. Das Inventar muss automatisiert gepflegt werden und mit dem Asset-Inventar verknüpft sein.", descriptionEn: "The organisation must maintain a central patch inventory documenting the current patch level, installed patches, outstanding patches, and patch history for each system. The inventory must be maintained automatically and linked to the asset inventory.", reason: "Ohne zentrales Patch-Inventar ist der Überblick über den Patch-Status der gesamten IT-Landschaft unmöglich.", reasonEn: "Without a central patch inventory, an overview of the patch status of the entire IT landscape is impossible.", whenRequired: "Immer erforderlich.", whenRequiredEn: "Always required.", sources: ["ISO 27001:2022 A.5.9", "CIS Controls v8 1.1", "BSI IT-Grundschutz OPS.1.1.3"] },
  { id: "p22-c21", title: "Patch-Prozess-Review und kontinuierliche Verbesserung", titleEn: "Patch Process Review and Continuous Improvement", description: "Der Patch-Management-Prozess muss mindestens jährlich überprüft und verbessert werden. Lessons Learned aus Patch-bedingten Ausfällen, überfälligen Patches und Sicherheitsvorfällen müssen in die Prozessverbesserung einfließen. Benchmark-Vergleiche mit Industriestandards müssen durchgeführt werden.", descriptionEn: "The patch management process must be reviewed and improved at least annually. Lessons learned from patch-related outages, overdue patches, and security incidents must inform process improvement. Benchmark comparisons with industry standards must be conducted.", reason: "Kontinuierliche Verbesserung stellt sicher, dass der Patch-Prozess mit den wachsenden Anforderungen Schritt hält.", reasonEn: "Continuous improvement ensures the patch process keeps pace with growing requirements.", whenRequired: "Mindestens jährlich.", whenRequiredEn: "At least annually.", sources: ["ISO 27001:2022 §10.1", "BSI IT-Grundschutz OPS.1.1.3", "NIST CSF 2.0 ID.IM"] },
];

